CREATE OR REPLACE FUNCTION company_admin_private.apply_invite_options(invitation uuid, target uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare saved company_admin_private.invitation_access%rowtype;i public.company_user_invites%rowtype;
 target_role text;keys text[];k boolean;h boolean;r text;
begin
 select * into strict i from public.company_user_invites where id=invitation for update;
 select * into saved from company_admin_private.invitation_access where invite_id=invitation for update;
 if not found or saved.applied_at is not null then return;end if;
 if jsonb_build_object('email',i.email,'company_name',i.company_name,'company_role',i.company_role,'invited_by',i.invited_by,'created_at',i.created_at) is distinct from saved.expected_invite
 then raise exception 'Invitasjonen er endret. Be administrator sende den på nytt med ønskede tilganger.' using errcode='40001';end if;
 if i.accepted_user_id is distinct from target or not coalesce(i.accepted,false) or i.status<>'accepted' or
  not exists(select 1 from public.profiles where id=target and approved and not coalesce(deactivated,false))
 then raise exception 'Invitasjonen er ikke bekreftet for en aktiv bruker.' using errcode='42501';end if;
 perform company_admin_private.validate_invite_options(saved.company_id,saved.inviter_id,saved.options);
 select workspace_role into target_role from public.sales_company_memberships where company_id=saved.company_id and user_id=target for share;
 if target_role is null then raise exception 'Brukeren mangler firmatilknytning.' using errcode='42501';end if;
 k:=(saved.options->>'kshms')::boolean;h:=(saved.options->>'hr')::boolean;r:=saved.options->>'kshms_role';
 if h then
  -- Same lock order as HR setup: configuration before member grants/HR rows.
  perform pg_advisory_xact_lock(hashtextextended('hr-foundation:'||saved.company_id::text,0));
  perform 1 from hr_private.firms where company_id=saved.company_id for update;
 end if;
 if target_role<>'firmaadmin' then
  -- Preserve the same responsible-person and closed-employment invariants as PeopleModuleAccess.
  if h and exists(select 1 from hr_private.closed_employments where company_id=saved.company_id and user_id=target)
  then raise exception 'Avsluttet arbeidsforhold kan ikke få HR-tilgang.' using errcode='42501';end if;
  if (not k or r<>'responsible') and exists(select 1 from public.kshms_settings where company_id=saved.company_id and responsible_user_id=target)
  then raise exception 'Velg ny KS/HMS-ansvarlig før denne tilgangen fjernes.' using errcode='42501';end if;
  insert into public.kshms_member_access(company_id,user_id,role,enabled,changed_by) values(saved.company_id,target,r,k,saved.inviter_id)
   on conflict(company_id,user_id) do update set role=excluded.role,enabled=excluded.enabled,changed_by=excluded.changed_by,changed_at=now();
  insert into hr_private.module_access(company_id,user_id,enabled,changed_by) values(saved.company_id,target,h,saved.inviter_id)
   on conflict(company_id,user_id) do update set enabled=excluded.enabled,changed_by=excluded.changed_by,changed_at=now();
 end if;
 if saved.new_account then
  select coalesce(array_agg(v),array[]::text[]) into keys from jsonb_array_elements_text(saved.options->'module_keys') v;
  delete from public.user_module_access where user_id=target;
  insert into public.user_module_access(user_id,module_key,granted_by) select target,v,saved.inviter_id from unnest(keys) v;
 end if;
 insert into public.kshms_audit(company_id,actor_id,action,object_id) values(saved.company_id,saved.inviter_id,'invitation_modules_applied',target);
 update company_admin_private.invitation_access set applied_at=now() where invite_id=invitation;
 if h then perform company_admin_private.enroll_invited_hr_users(saved.company_id,target);end if;
end $function$

CREATE OR REPLACE FUNCTION public.company_admin_set_role(p_company_id uuid, p_user_id uuid, p_expected_role text, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m public.sales_company_memberships%rowtype; p public.profiles%rowtype;
begin
 perform company_admin_private.require_manager(p_company_id);
 if p_role is null or p_role not in ('ansatt','firmaadmin') then raise exception 'Ugyldig rolle.' using errcode='22023'; end if;
 select * into p from public.profiles where id=p_user_id for update;
 select * into m from public.sales_company_memberships where company_id=p_company_id and user_id=p_user_id for update;
 if m.user_id is null or p_user_id=auth.uid() or p.system_role='systemadmin' then
  raise exception 'Denne brukerrollen kan ikke endres her.' using errcode='42501'; end if;
 if m.workspace_role is distinct from p_expected_role then raise exception 'Rollen er endret. Hent på nytt.' using errcode='40001'; end if;
 if m.is_primary then
  -- Preserve the existing profile guard and primary-workspace synchronization.
  update public.profiles set company_role=p_role where id=p_user_id;
 else
  update public.sales_company_memberships set workspace_role=p_role,updated_at=now(),granted_by=auth.uid()
   where company_id=p_company_id and user_id=p_user_id;
 end if;
 return public.company_admin_snapshot(p_company_id);
end $function$

CREATE OR REPLACE FUNCTION public.company_admin_set_status(p_company_id uuid, p_user_id uuid, p_expected jsonb, p_deactivated boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.profiles%rowtype;
begin
 perform company_admin_private.require_manager(p_company_id);
 if not public.current_profile_is_systemadmin() or p_user_id=auth.uid() or p_deactivated is null then
  raise exception 'Kontostatus styres av systemadministrator og gjelder alle firmaer.' using errcode='42501'; end if;
 select * into p from public.profiles where id=p_user_id for update;
 if p.id is null or p.system_role='systemadmin' or not exists(select 1 from public.sales_company_memberships where company_id=p_company_id and user_id=p_user_id)
 then raise exception 'Brukeren kan ikke endres her.' using errcode='42501'; end if;
 if jsonb_build_object('approved',p.approved,'deactivated',p.deactivated) is distinct from p_expected
 then raise exception 'Kontostatus er endret. Hent på nytt.' using errcode='40001'; end if;
 update public.profiles set approved=not p_deactivated,deactivated=p_deactivated where id=p_user_id;
 return public.company_admin_snapshot(p_company_id);
end $function$

CREATE OR REPLACE FUNCTION public.controller_access_command(p_project_id uuid, p_action text, p_id uuid, p_code text, p_name text, p_expires_at timestamp with time zone, p_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare p public.projects%rowtype;l controller_private.links%rowtype;begin
 p:=controller_private.project_access(p_project_id);
 if p_id is null or p_action not in ('create','extend','rotate','revoke') then raise exception 'Ugyldig handling.';end if;
 if p_action in ('create','extend') and (p_expires_at is null or not isfinite(p_expires_at) or p_expires_at<=clock_timestamp()) then raise exception 'Velg en utløpsdato i fremtiden.';end if;
 if p_action in ('create','rotate') and (p_code is null or p_code !~ '^[A-F0-9]{32}$') then raise exception 'Tilgangskoden må genereres på nytt.';end if;
 if p_action='create' then
  if nullif(trim(p_name),'') is null or length(trim(p_name))>160 or p_revision is distinct from 0 then raise exception 'Skriv kontrollørens navn eller firma.';end if;
  insert into controller_private.links(id,project_id,company_id,name,code_hash,expires_at,created_by,updated_by)
  values(p_id,p.id,p.company_scope_id,trim(p_name),sha256(convert_to(p_code,'UTF8')),p_expires_at,auth.uid(),auth.uid()) on conflict(id) do nothing;
  select * into l from controller_private.links where id=p_id for update;
  if l.project_id<>p.id or l.company_id<>p.company_scope_id or l.created_by<>auth.uid() or l.code_hash<>sha256(convert_to(p_code,'UTF8')) or l.name<>trim(p_name) or l.expires_at<>p_expires_at or l.revoked_at is not null then raise exception 'Tilgangen er endret. Oppdater siden.' using errcode='40001';end if;
 else
  select * into l from controller_private.links where id=p_id and project_id=p.id and company_id=p.company_scope_id for update;
  if l.id is null then raise exception 'Tilgangen finnes ikke i dette prosjektet.' using errcode='42501';end if;
  if l.revision is distinct from p_revision or l.revoked_at is not null then raise exception 'Tilgangen er endret. Oppdater siden.' using errcode='40001';end if;
  update controller_private.links set expires_at=case when p_action='extend' then p_expires_at else expires_at end,
   code_hash=case when p_action='rotate' then sha256(convert_to(p_code,'UTF8')) else code_hash end,
   revoked_at=case when p_action='revoke' then clock_timestamp() else revoked_at end,
   revision=revision+1,updated_at=clock_timestamp(),updated_by=auth.uid() where id=p_id returning * into l;
 end if;
 return jsonb_build_object('id',l.id,'revision',l.revision);end;$function$

CREATE OR REPLACE FUNCTION public.hr_contact_save(p_company_id uuid, p_employee_id uuid, p_employee_revision integer, p_contact_revision integer, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x jsonb;e hr_private.employees%rowtype;old_revision integer;fields jsonb:='{}';k text;v text;r date;
begin
 -- Same lock order as register/closure: firm then employee. Fresh access each call.
 select review_on into r from hr_private.firms where company_id=p_company_id for update;
 x:=hr_private.require_context(p_company_id);perform hr_private.require_content_ready();
 select * into e from hr_private.employees where company_id=p_company_id and id=p_employee_id for update;
 if e.id is null or e.user_id is distinct from auth.uid() or not hr_private.can_read(p_company_id,e,auth.uid())
 then raise exception 'Bare medarbeideren kan endre egen kontaktprofil.' using errcode='42501';end if;
 if e.revision is distinct from p_employee_revision then raise exception 'Medarbeidertilgangen er endret.' using errcode='40001';end if;
 if r is null or r<(now() at time zone 'Europe/Oslo')::date then raise exception 'Firmaadmin må fornye HR-kontrollfristen før lagring.' using errcode='22023';end if;
 if p_data is null or jsonb_typeof(p_data)<>'object' or pg_column_size(p_data)>6000
 then raise exception 'Ugyldig kontaktprofil.' using errcode='22023';end if;
 for k,v in select key,value from jsonb_each_text(p_data) loop
  if k not in ('address','postal_code','city','relative_name','relative_relationship','relative_phone','relative_email') or jsonb_typeof(p_data->k)<>'string'
  then raise exception 'Ugyldig kontaktfelt.' using errcode='22023';end if;
  v:=trim(v);
  if length(v)>(case k when 'address' then 160 when 'postal_code' then 20 when 'city' then 80 when 'relative_name' then 120 when 'relative_relationship' then 60 when 'relative_phone' then 40 else 254 end)
  then raise exception 'Kontaktfeltet er for langt.' using errcode='22023';end if;
  if v<>'' then fields:=fields||jsonb_build_object(k,v);end if;
 end loop;
 select coalesce(max((payload->>'revision')::integer),0) into old_revision from hr_private.artifacts
  where company_id=p_company_id and employee_id=e.id and kind='content' and payload->>'type'='contact_profile';
 if old_revision is distinct from p_contact_revision then raise exception 'Kontaktprofilen er endret i en annen økt.' using errcode='40001';end if;
 -- Contact corrections replace earlier values; no unnecessary relative history.
 delete from hr_private.artifacts where company_id=p_company_id and employee_id=e.id and kind='content' and payload->>'type'='contact_profile';
 insert into hr_private.artifacts(company_id,employee_id,employee_revision,kind,payload,review_on)
 values(p_company_id,e.id,e.revision,'content',jsonb_build_object('type','contact_profile','revision',old_revision+1,'data',fields),r);
 return jsonb_build_object('context',x,'employee',jsonb_build_object('id',e.id,'revision',e.revision),'revision',old_revision+1);
end$function$

CREATE OR REPLACE FUNCTION public.hr_content_purge(p_company_id uuid, p_employee_id uuid, p_revision integer, p_confirm text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare x jsonb;e hr_private.employees%rowtype;r uuid:=gen_random_uuid();begin
 perform 1 from hr_private.firms where company_id=p_company_id for update;
 x:=hr_private.require_context(p_company_id,true);
 select * into e from hr_private.employees where company_id=p_company_id and id=p_employee_id for update;
 if e.id is null then raise exception 'HR-medarbeideren er ikke tilgjengelig.' using errcode='42501';end if;
 if e.revision is distinct from p_revision then raise exception 'HR-registeret er endret.' using errcode='40001';end if;
 if p_confirm is distinct from 'PURGE_CONTENT' then raise exception 'Bekreft innholdssletting uttrykkelig.' using errcode='22023';end if;
 perform hr_private.purge_resources(e,r,'content',e.revision);
 update hr_private.employees set revision=revision+1 where id=e.id;
 return jsonb_build_object('context',x,'receipt_id',r,'access_blocked',true,'purge_state',(select state from hr_private.purge_receipts where id=r));
end$function$

CREATE OR REPLACE FUNCTION public.hr_conversation_command(p_company_id uuid, p_employee_id uuid, p_employee_revision integer, p_conversation_id uuid, p_revision integer, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e hr_private.employees%rowtype;t hr_private.conversations%rowtype;v jsonb;a jsonb;q jsonb;keys text[];
 aid uuid:=gen_random_uuid();is_employee boolean;is_leader boolean;side text;changed boolean:=true;notify_feedback boolean:=false;owner uuid;ids uuid[]:='{}';qid uuid;
begin
 perform 1 from hr_private.firms where company_id=p_company_id for update;
 e:=hr_private.conversation_employee(p_company_id,p_employee_id);
 if p_employee_revision is distinct from e.revision then raise exception 'Medarbeiderens tilgang er endret.' using errcode='40001';end if;
 select * into t from hr_private.conversations where company_id=p_company_id and employee_id=e.id and id=p_conversation_id for update;
 if t.id is null then raise exception 'Samtalen er ikke tilgjengelig.' using errcode='42501';end if;
 if p_revision is distinct from t.revision then raise exception 'Samtalen er endret. Arbeidet ditt er beholdt; hent ny utgave.' using errcode='40001';end if;
 select payload into v from hr_private.artifacts where id=t.current_artifact_id;
 -- Mutations retain the private preparation; redaction is only for responses.
 if v#>>'{confirmations,leader,user_id}' is distinct from e.leader_id::text then
  v:=jsonb_set(v,'{confirmations,leader}','null'::jsonb);
  if v->>'stage'='completed' then v:=jsonb_set(v,'{stage}','"awaiting"'::jsonb);end if;
 end if;
 is_employee:=coalesce(auth.uid()=e.user_id,false);is_leader:=coalesce(auth.uid()=e.leader_id,false);
 if p_action is null or p_action not in('preparation','share','meeting','ready','comment','confirm','revise')
 or jsonb_typeof(p_data) is distinct from 'object' or octet_length(p_data::text)>180000 then
  raise exception 'Ugyldig samtalehandling.' using errcode='22023';end if;
 keys:=case p_action when 'preparation' then array['answers'] when 'meeting' then array['answers','actions','next_on']
 when 'comment' then array['text'] else '{}'::text[] end;
 if exists(select 1 from jsonb_object_keys(p_data) k where not k=any(keys)) or not p_data ?& keys then
  raise exception 'Ukjente eller manglende samtalefelt.' using errcode='22023';end if;
 notify_feedback:=is_employee and(p_action='share' or(p_action='comment' and v#>'{comments,employee}' is distinct from p_data->'text'));
 if p_action in('preparation','share') then
  if not is_employee or v->>'stage'<>'preparation' then raise exception 'Bare medarbeideren kan forberede sin åpne kladd.' using errcode='42501';end if;
  a:=case when p_action='preparation' then p_data->'answers' else v->'preparation' end;
  perform hr_private.validate_conversation_answers(a,v->'template','preparation',p_action='share');
  v:=jsonb_set(v,'{preparation}',a);
  if p_action='share' then v:=v||jsonb_build_object('stage','meeting','shared',true);end if;
 elsif p_action in('meeting','ready','revise') then
  if not is_leader then raise exception 'Bare nærmeste leder redigerer møtereferatet.' using errcode='42501';end if;
  if p_action='revise' then
   if v->>'stage' not in('awaiting','completed') then raise exception 'Referatet er allerede åpent.' using errcode='22023';end if;
   v:=jsonb_set(v,'{stage}','"meeting"'::jsonb);
  else
   if v->>'stage' not in('meeting','awaiting') then raise exception 'Medarbeideren må dele forberedelsen først.' using errcode='22023';end if;
   if p_action='meeting' then
    perform hr_private.validate_conversation_answers(p_data->'answers',v->'template','meeting',false);
    if jsonb_typeof(p_data->'actions') is distinct from 'array' or jsonb_array_length(p_data->'actions')>12
    or jsonb_typeof(p_data->'next_on') is distinct from 'string' then raise exception 'Ugyldige tiltak eller oppfølgingsdato.' using errcode='22023';end if;
    if p_data->>'next_on'<>'' then
     if p_data->>'next_on' !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Ugyldig oppfølgingsdato.' using errcode='22023';end if;
     perform(p_data->>'next_on')::date;
    end if;
    for q in select value from jsonb_array_elements(p_data->'actions') loop
     if jsonb_typeof(q) is distinct from 'object' or not q ?& array['id','task','owner_id','due_on','done']
     or exists(select 1 from jsonb_object_keys(q) k where not k=any(array['id','task','owner_id','due_on','done']))
     or jsonb_typeof(q->'task') is distinct from 'string' or length(trim(q->>'task')) not between 1 and 600
     or jsonb_typeof(q->'done') is distinct from 'boolean' or jsonb_typeof(q->'due_on') is distinct from 'string'
     or q->>'due_on' !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Hvert tiltak trenger oppgave, ansvarlig og frist.' using errcode='22023';end if;
     qid:=(q->>'id')::uuid;owner:=(q->>'owner_id')::uuid;
     if qid is null or qid=any(ids) or owner is null or (owner is distinct from e.user_id and owner is distinct from e.leader_id)
      or not hr_private.active_member(p_company_id,owner) then raise exception 'Velg medarbeideren eller lederen som ansvarlig.' using errcode='22023';end if;
     ids:=array_append(ids,qid);perform(q->>'due_on')::date;
    end loop;
    if jsonb_array_length(p_data->'actions')>0 and p_data->>'next_on'='' then raise exception 'Velg neste oppfølgingsdato når tiltak er avtalt.' using errcode='22023';end if;
    v:=v||jsonb_build_object('meeting',p_data->'answers','actions',p_data->'actions','next_on',p_data->>'next_on','stage','meeting');
   else
    perform hr_private.validate_conversation_answers(v->'meeting',v->'template','meeting',true);
    -- Retrying an already submitted review must preserve its confirmations/history.
    if v->>'stage'='awaiting' then return public.hr_conversation_get(p_company_id,e.id,t.id);end if;
    v:=jsonb_set(v,'{stage}','"awaiting"'::jsonb);
   end if;
  end if;
 elsif p_action='comment' then
  if not(is_employee or is_leader) or not(v->>'shared')::boolean then raise exception 'Bare partene kan legge til egne kommentarer.' using errcode='42501';end if;
  if jsonb_typeof(p_data->'text') is distinct from 'string' or length(p_data->>'text')>4000 then raise exception 'Kommentaren er for lang.' using errcode='22023';end if;
  side:=case when is_employee then 'employee' else 'leader' end;
  v:=jsonb_set(v,array['comments',side],p_data->'text');
  if v->>'stage'='completed' then v:=jsonb_set(v,'{stage}','"awaiting"'::jsonb);end if;
 else
  if not(is_employee or is_leader) or v->>'stage' not in('awaiting','completed') then raise exception 'Begge parter bekrefter selv etter gjennomgang.' using errcode='42501';end if;
  changed:=false;side:=case when is_employee then 'employee' else 'leader' end;
  if v#>>array['confirmations',side,'user_id']=auth.uid()::text then return public.hr_conversation_get(p_company_id,e.id,t.id);end if;
  v:=jsonb_set(v,array['confirmations',side],jsonb_build_object('user_id',auth.uid(),'at',now(),'content_version',v->'content_version'));
  if v#>>'{confirmations,employee,user_id}'=e.user_id::text and v#>>'{confirmations,leader,user_id}'=e.leader_id::text then
   v:=jsonb_set(v,'{stage}','"completed"'::jsonb);end if;
 end if;
 if changed then v:=v||jsonb_build_object('content_version',(v->>'content_version')::integer+1,
 'confirmations',jsonb_build_object('employee',null,'leader',null));end if;
 v:=v||jsonb_build_object('revision',t.revision+1,'leader_id',e.leader_id,'saved_at',now(),'saved_by',auth.uid());
 if notify_feedback then v:=v||jsonb_build_object('employee_feedback_revision',t.revision+1);end if;
 insert into hr_private.artifacts(id,company_id,employee_id,employee_revision,kind,payload,review_on)
 values(aid,p_company_id,e.id,e.revision,'version',v,(select review_on from hr_private.firms where company_id=p_company_id));
 update hr_private.conversations set revision=revision+1,current_artifact_id=aid where id=t.id;
 if notify_feedback then perform hr_private.queue_conversation_feedback(p_company_id,e.id,t.id);end if;
 return public.hr_conversation_get(p_company_id,e.id,t.id);
end$function$

CREATE OR REPLACE FUNCTION public.hr_conversation_feedback_handle(p_company_id uuid, p_employee_id uuid, p_employee_revision integer, p_conversation_id uuid, p_feedback_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare e hr_private.employees%rowtype;c hr_private.conversations%rowtype;v jsonb;x jsonb;begin
 -- Same lock order as conversation commands/leader changes. Never modify the case or outbox.
 perform 1 from hr_private.firms where company_id=p_company_id for update;
 e:=hr_private.conversation_employee(p_company_id,p_employee_id);
 if auth.uid() is distinct from e.leader_id or not hr_private.has_module_access(p_company_id,e.user_id) then
 raise exception 'Bare gjeldende nærmeste leder håndterer innspillet.' using errcode='42501';end if;
 if p_employee_revision is distinct from e.revision then raise exception 'Medarbeiderens tilgang er endret.' using errcode='40001';end if;
 select * into c from hr_private.conversations where company_id=p_company_id and employee_id=e.id and id=p_conversation_id for update;
 if c.id is null then raise exception 'Samtalen er ikke tilgjengelig.' using errcode='42501';end if;
 select payload into v from hr_private.artifacts where id=c.current_artifact_id;
 if p_feedback_revision is null or p_feedback_revision<1 or v->>'shared' is distinct from 'true'
 or p_feedback_revision is distinct from coalesce((v->>'employee_feedback_revision')::integer,0) then
 raise exception 'Innspillet er endret. Åpne det nyeste innspillet før du markerer det som håndtert.' using errcode='40001';end if;
 insert into hr_private.conversation_feedback_receipts(conversation_id,leader_id,feedback_revision)
 values(c.id,auth.uid(),p_feedback_revision)
 on conflict(conversation_id,leader_id) do update set feedback_revision=excluded.feedback_revision,handled_at=now()
 where hr_private.conversation_feedback_receipts.feedback_revision<excluded.feedback_revision;
 x:=hr_private.require_context(p_company_id);
 return jsonb_build_object('context',x,'employee_id',e.id,'conversation_id',c.id,'feedback_revision',p_feedback_revision,'handled',true);
end$function$

CREATE OR REPLACE FUNCTION public.hr_conversation_notify(p_company_id uuid, p_employee_id uuid, p_employee_revision integer, p_conversation_id uuid, p_revision integer)
