CREATE OR REPLACE FUNCTION public.hr_employee_command(p_company_id uuid, p_action text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x jsonb; e hr_private.employees%rowtype; d hr_private.closed_employments%rowtype;
 employee_target uuid; u uuid; leader uuid; rev integer; reader uuid; keys text[];
begin
 -- All H1 mutations are firmadmin-only and serialize at the firm boundary.
 perform 1 from hr_private.firms where company_id=p_company_id for update;
 x:=hr_private.require_context(p_company_id,true);
 if p_action not in ('create','leader','reader','revoke_reader','end') or p_action is null or jsonb_typeof(p_payload) is distinct from 'object' then raise exception 'Ugyldig HR-handling.' using errcode='22023'; end if;
 keys:=case p_action when 'create' then array['user_id','leader_id'] when 'leader' then array['id','revision','leader_id','clear_old_leader_reader'] when 'reader' then array['id','revision','reader_id','reason'] when 'revoke_reader' then array['id','revision','reader_id'] else array['id','revision','confirm'] end;
 if exists(select 1 from jsonb_object_keys(p_payload) k where not k=any(keys)) then raise exception 'Innhold eller ukjente felt kan ikke lagres i HR-fundamentet.' using errcode='22023'; end if;
 if p_action='create' then
  u:=(p_payload->>'user_id')::uuid; leader:=(p_payload->>'leader_id')::uuid;
  if not hr_private.active_member(p_company_id,u) or (leader is not null and (leader=u or not hr_private.active_member(p_company_id,leader))) then raise exception 'Velg aktive interne brukere i samme firma.' using errcode='42501'; end if;
  insert into hr_private.employees(company_id,user_id,leader_id) values(p_company_id,u,leader) returning * into e;
 else
  employee_target:=(p_payload->>'id')::uuid; rev:=(p_payload->>'revision')::integer;
  select * into e from hr_private.employees where company_id=p_company_id and employees.id=employee_target for update;
  if e.id is null then
   -- Idempotent acknowledgement after a lost closure response, no resurrection.
   select * into d from hr_private.closed_employments where company_id=p_company_id and employee_id=employee_target;
   if p_action='end' and d.employee_id is not null and rev=d.previous_revision and p_payload->>'confirm'='END_AND_DELETE' then
    return hr_private.closure_json(p_company_id,d.employee_id,x);
   end if;
   raise exception 'HR-medarbeideren er ikke tilgjengelig.' using errcode='42501';
  end if;
  if rev is distinct from e.revision then raise exception 'HR-registeret er endret. Hent på nytt.' using errcode='40001'; end if;
  if p_action='leader' then
   leader:=(p_payload->>'leader_id')::uuid;
   if leader is not null and (leader=e.user_id or not hr_private.active_member(p_company_id,leader)) then raise exception 'Velg en aktiv leder i samme firma.' using errcode='42501'; end if;
   if leader is distinct from e.leader_id and exists(select 1 from hr_private.readers where employee_id=e.id and user_id=e.leader_id) then
    if p_payload->>'clear_old_leader_reader' is distinct from 'true' then raise exception 'Tidligere leder har ekstra lesetilgang. Fjern den uttrykkelig før lederbyttet.' using errcode='22023'; end if;
    delete from hr_private.readers where employee_id=e.id and user_id=e.leader_id;
   end if;
   update hr_private.employees set leader_id=leader,revision=revision+1 where employees.id=e.id returning * into e;
  elsif p_action in ('reader','revoke_reader') then
   reader:=(p_payload->>'reader_id')::uuid;
   if reader is null or reader=e.user_id then raise exception 'Velg en annen aktiv leser.' using errcode='22023'; end if;
   if p_action='reader' then
    if not hr_private.active_member(p_company_id,reader) then raise exception 'Leser er ikke aktiv i samme firma.' using errcode='42501'; end if;
    insert into hr_private.readers(company_id,employee_id,user_id,granted_by,reason) values(p_company_id,e.id,reader,auth.uid(),p_payload->>'reason')
    on conflict(employee_id,user_id) do update set granted_by=excluded.granted_by,granted_at=now(),reason=excluded.reason;
   else delete from hr_private.readers where employee_id=e.id and user_id=reader; end if;
   update hr_private.employees set revision=revision+1 where employees.id=e.id returning * into e;
  elsif p_action='end' then
   if p_payload->>'confirm' is distinct from 'END_AND_DELETE' then raise exception 'Bekreft avslutning og sletting uttrykkelig.' using errcode='22023'; end if;
   insert into hr_private.closed_employments(employee_id,company_id,user_id,previous_revision) values(e.id,p_company_id,e.user_id,e.revision) returning * into d;
   -- Remove the departing person's explicit grants and leader assignments elsewhere.
   update hr_private.employees o set revision=o.revision+1,leader_id=case when o.leader_id=e.user_id then null else o.leader_id end
    where o.company_id=p_company_id and o.id<>e.id and (o.leader_id=e.user_id or exists(select 1 from hr_private.readers r where r.employee_id=o.id and r.user_id=e.user_id));
   delete from hr_private.readers where company_id=p_company_id and user_id=e.user_id;
   delete from hr_private.employees where employees.id=e.id; -- cascades all readers/reasons
   return hr_private.closure_json(p_company_id,d.employee_id,x);
  end if;
 end if;
 return jsonb_build_object('context',x,'employee',hr_private.employee_json(e),'content_enabled',false);
end $function$

CREATE OR REPLACE FUNCTION public.hr_foundation_configure(p_company_id uuid, p_revision integer, p_enabled boolean, p_purpose text, p_legal_basis text, p_review_on date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x jsonb; f hr_private.firms%rowtype;
begin
 -- Serialize initial configuration too; does not alter company entitlements.
 perform pg_advisory_xact_lock(hashtextextended('hr-foundation:'||p_company_id::text,0));
 x:=hr_private.require_actor(p_company_id,true);
 select * into f from hr_private.firms where company_id=p_company_id for update;
 if p_revision is distinct from coalesce(f.revision,0) then raise exception 'HR-oppsettet er endret. Hent på nytt.' using errcode='40001'; end if;
 if p_enabled is null or p_review_on is null or p_review_on<(now() at time zone 'Europe/Oslo')::date
 or p_review_on>(now() at time zone 'Europe/Oslo')::date+366 then raise exception 'Velg en ny kontrollfrist innen ett år.' using errcode='22023'; end if;
 insert into hr_private.firms(company_id,enabled,purpose,legal_basis,review_on,revision)
 values(p_company_id,p_enabled,p_purpose,p_legal_basis,p_review_on,coalesce(f.revision,0)+1)
 on conflict(company_id) do update set enabled=excluded.enabled,purpose=excluded.purpose,legal_basis=excluded.legal_basis,review_on=excluded.review_on,revision=excluded.revision
 returning * into f;
 return jsonb_build_object('context',x,'settings',to_jsonb(f),'content_enabled',false);
end $function$

CREATE OR REPLACE FUNCTION public.hr_sick_leave_command(p_company_id uuid, p_employee_id uuid, p_employee_revision integer, p_conversation_id uuid, p_revision integer, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e hr_private.employees%rowtype;t hr_private.sick_leave_cases%rowtype;v jsonb;a jsonb;q jsonb;keys text[];
 aid uuid:=gen_random_uuid();is_employee boolean;is_leader boolean;side text;changed boolean:=true;owner uuid;ids uuid[]:='{}';qid uuid;
begin
 perform 1 from hr_private.firms where company_id=p_company_id for update;
 e:=hr_private.conversation_employee(p_company_id,p_employee_id);
 if p_employee_revision is distinct from e.revision then raise exception 'Medarbeiderens tilgang er endret.' using errcode='40001';end if;
 select * into t from hr_private.sick_leave_cases where company_id=p_company_id and employee_id=e.id and id=p_conversation_id for update;
 if t.id is null then raise exception 'Oppfølgingen er ikke tilgjengelig.' using errcode='42501';end if;
 if p_revision is distinct from t.revision then raise exception 'Oppfølgingen er endret. Arbeidet ditt er beholdt; hent ny utgave.' using errcode='40001';end if;
 select payload into v from hr_private.artifacts where id=t.current_artifact_id;
 -- Mutations retain the private preparation; redaction is only for responses.
 if v#>>'{confirmations,leader,user_id}' is distinct from e.leader_id::text then
  v:=jsonb_set(v,'{confirmations,leader}','null'::jsonb);
  if v->>'stage'='completed' then v:=jsonb_set(v,'{stage}','"awaiting"'::jsonb);end if;
 end if;
 is_employee:=coalesce(auth.uid()=e.user_id,false);is_leader:=coalesce(auth.uid()=e.leader_id,false);
 if p_action is null or p_action not in('preparation','share','meeting','ready','comment','confirm','revise','followup','log_sharing','close','reopen')
 or jsonb_typeof(p_data) is distinct from 'object' or octet_length(p_data::text)>180000 then
  raise exception 'Ugyldig oppfølgingshandling.' using errcode='22023';end if;
 keys:=case p_action when 'preparation' then array['answers'] when 'meeting' then array['answers','actions','next_on']
 when 'comment' then array['text'] when 'followup' then array['on','absence_mode','milestones','correction_reason'] when 'log_sharing' then array['target','on','version','channel','confirmed'] when 'close' then array['on','confirmed'] else '{}'::text[] end;
 if exists(select 1 from jsonb_object_keys(p_data) k where not k=any(keys)) or not p_data ?& keys then
  raise exception 'Ukjente eller manglende samtalefelt.' using errcode='22023';end if;
 if v->>'case_status'='closed' and p_action<>'reopen' then raise exception 'Oppfølgingen er avsluttet. Leder må gjenåpne før redigering.' using errcode='22023';end if;
 if p_action in('followup','log_sharing','close','reopen') then
  if not is_leader then raise exception 'Bare nærmeste leder følger opp saken.' using errcode='42501';end if;
  if p_action='followup' then
   perform hr_private.validate_sick_followup(p_data,v);
   v:=v||jsonb_build_object('on',p_data->>'on','absence_mode',p_data->>'absence_mode','milestones',p_data->'milestones','correction_reason',p_data->>'correction_reason');
   if v->>'stage'='completed' then v:=jsonb_set(v,'{stage}','"awaiting"'::jsonb);end if;
  elsif p_action='log_sharing' then
   if jsonb_typeof(p_data->'target') is distinct from 'string' or jsonb_typeof(p_data->'channel') is distinct from 'string' or jsonb_typeof(p_data->'on') is distinct from 'string' or p_data->>'target' not in('sykmelder','nav') or p_data->>'channel' not in('nav_portal','paper','other') or p_data->'confirmed' is distinct from 'true'::jsonb
    or jsonb_typeof(p_data->'version') is distinct from 'number' or (p_data->>'version')::integer<1 or (p_data->>'version')::integer>t.revision
    or p_data->>'on' !~ '^\d{4}-\d{2}-\d{2}$' or (p_data->>'on')::date>(now() at time zone 'Europe/Oslo')::date or (p_data->>'on')::date<(v->>'on')::date
    or not exists(select 1 from hr_private.artifacts a where a.company_id=p_company_id and a.employee_id=e.id and a.payload->>'type'='sickleave' and a.payload->>'id'=t.id::text and a.payload->>'revision'=p_data->>'version' and (a.payload->>'shared')::boolean)
   then raise exception 'Velg faktisk delt utgave, dato og kanal. Bekreft delingen.' using errcode='22023';end if;
   if jsonb_array_length(v#>array['sharing',p_data->>'target'])>=100 then raise exception 'Kontroller delingshistorikken før flere registreringer.' using errcode='22023';end if;
   v:=jsonb_set(v,array['sharing',p_data->>'target'],(v#>array['sharing',p_data->>'target'])||jsonb_build_array(p_data||jsonb_build_object('recorded_at',now(),'recorded_by',auth.uid())));changed:=false;
  elsif p_action='close' then
   if jsonb_typeof(p_data->'on') is distinct from 'string' or p_data->'confirmed' is distinct from 'true'::jsonb or p_data->>'on' !~ '^\d{4}-\d{2}-\d{2}$'
    or (p_data->>'on')::date<(v->>'on')::date or (p_data->>'on')::date>(now() at time zone 'Europe/Oslo')::date
   then raise exception 'Velg faktisk avslutningsdato og bekreft avslutning.' using errcode='22023';end if;
   v:=v||jsonb_build_object('case_status','closed','returned_on',p_data->>'on');changed:=false;
  else
   if v->>'case_status'<>'closed' then raise exception 'Oppfølgingen er allerede aktiv.' using errcode='22023';end if;
   if exists(select 1 from hr_private.sick_leave_cases other join hr_private.artifacts a on a.id=other.current_artifact_id where other.company_id=p_company_id and other.employee_id=e.id and other.id<>t.id and a.payload->>'case_status'='active') then raise exception 'En annen oppfølging er aktiv. Åpne den først.' using errcode='22023';end if;
   v:=v||jsonb_build_object('case_status','active','returned_on','');changed:=false;
  end if;
 elsif p_action in('preparation','share') then
  if not is_employee or v->>'stage'<>'preparation' then raise exception 'Bare medarbeideren kan forberede sin åpne kladd.' using errcode='42501';end if;
  a:=case when p_action='preparation' then p_data->'answers' else v->'preparation' end;
  perform hr_private.validate_conversation_answers(a,v->'template','preparation',p_action='share');
  v:=jsonb_set(v,'{preparation}',a);
  if p_action='share' then v:=v||jsonb_build_object('stage','meeting','shared',true);end if;
 elsif p_action in('meeting','ready','revise') then
  if not is_leader then raise exception 'Bare nærmeste leder redigerer møtereferatet.' using errcode='42501';end if;
  if p_action='revise' then
   if v->>'stage' not in('awaiting','completed') then raise exception 'Referatet er allerede åpent.' using errcode='22023';end if;
   v:=jsonb_set(v,'{stage}','"meeting"'::jsonb);
  else
   if v->>'stage' not in('meeting','awaiting') then raise exception 'Medarbeideren må dele forberedelsen først.' using errcode='22023';end if;
   if p_action='meeting' then
    perform hr_private.validate_conversation_answers(p_data->'answers',v->'template','meeting',false);
    if jsonb_typeof(p_data->'actions') is distinct from 'array' or jsonb_array_length(p_data->'actions')>12
    or jsonb_typeof(p_data->'next_on') is distinct from 'string' then raise exception 'Ugyldige tiltak eller oppfølgingsdato.' using errcode='22023';end if;
    if p_data->>'next_on'<>'' then
     if p_data->>'next_on' !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Ugyldig oppfølgingsdato.' using errcode='22023';end if;
     perform(p_data->>'next_on')::date;
    end if;
    for q in select value from jsonb_array_elements(p_data->'actions') loop
     if jsonb_typeof(q) is distinct from 'object' or not q ?& array['id','task','owner_id','due_on','done']
     or exists(select 1 from jsonb_object_keys(q) k where not k=any(array['id','task','owner_id','due_on','done']))
     or jsonb_typeof(q->'task') is distinct from 'string' or length(trim(q->>'task')) not between 1 and 600
     or jsonb_typeof(q->'done') is distinct from 'boolean' or jsonb_typeof(q->'due_on') is distinct from 'string'
     or q->>'due_on' !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Hvert tiltak trenger oppgave, ansvarlig og frist.' using errcode='22023';end if;
     qid:=(q->>'id')::uuid;owner:=(q->>'owner_id')::uuid;
     if qid is null or qid=any(ids) or owner is null or (owner is distinct from e.user_id and owner is distinct from e.leader_id)
      or not hr_private.active_member(p_company_id,owner) then raise exception 'Velg medarbeideren eller lederen som ansvarlig.' using errcode='22023';end if;
     ids:=array_append(ids,qid);perform(q->>'due_on')::date;
    end loop;
    if jsonb_array_length(p_data->'actions')>0 and p_data->>'next_on'='' then raise exception 'Velg neste oppfølgingsdato når tiltak er avtalt.' using errcode='22023';end if;
    v:=v||jsonb_build_object('meeting',p_data->'answers','actions',p_data->'actions','next_on',p_data->>'next_on','stage','meeting');
   else
    perform hr_private.validate_conversation_answers(v->'meeting',v->'template','meeting',true);
    v:=jsonb_set(v,'{stage}','"awaiting"'::jsonb);
   end if;
  end if;
 elsif p_action='comment' then
  if not(is_employee or is_leader) or not(v->>'shared')::boolean then raise exception 'Bare partene kan legge til egne kommentarer.' using errcode='42501';end if;
  if jsonb_typeof(p_data->'text') is distinct from 'string' or length(p_data->>'text')>4000 then raise exception 'Kommentaren er for lang.' using errcode='22023';end if;
  side:=case when is_employee then 'employee' else 'leader' end;
  v:=jsonb_set(v,array['comments',side],p_data->'text');
  if v->>'stage'='completed' then v:=jsonb_set(v,'{stage}','"awaiting"'::jsonb);end if;
 else
  if not(is_employee or is_leader) or v->>'stage' not in('awaiting','completed') then raise exception 'Begge parter bekrefter selv etter gjennomgang.' using errcode='42501';end if;
  changed:=false;side:=case when is_employee then 'employee' else 'leader' end;
  if v#>>array['confirmations',side,'user_id']=auth.uid()::text then return public.hr_sick_leave_get(p_company_id,e.id,t.id);end if;
  v:=jsonb_set(v,array['confirmations',side],jsonb_build_object('user_id',auth.uid(),'at',now(),'content_version',v->'content_version'));
  if v#>>'{confirmations,employee,user_id}'=e.user_id::text and v#>>'{confirmations,leader,user_id}'=e.leader_id::text then
   v:=jsonb_set(v,'{stage}','"completed"'::jsonb);end if;
 end if;
 if changed then v:=v||jsonb_build_object('content_version',(v->>'content_version')::integer+1,
 'confirmations',jsonb_build_object('employee',null,'leader',null));end if;
 v:=v||jsonb_build_object('revision',t.revision+1,'leader_id',e.leader_id,'saved_at',now(),'saved_by',auth.uid());
 insert into hr_private.artifacts(id,company_id,employee_id,employee_revision,kind,payload,review_on)
 values(aid,p_company_id,e.id,e.revision,'version',v,(select review_on from hr_private.firms where company_id=p_company_id));
 update hr_private.sick_leave_cases set revision=revision+1,current_artifact_id=aid where id=t.id;
 return public.hr_sick_leave_get(p_company_id,e.id,t.id);
end$function$

CREATE OR REPLACE FUNCTION public.hr_sick_leave_start(p_company_id uuid, p_employee_id uuid, p_employee_revision integer, p_conversation_id uuid, p_template_id uuid, p_template_revision integer, p_on date, p_mode text DEFAULT 'full'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e hr_private.employees%rowtype;t hr_private.conversation_templates%rowtype;tpl jsonb;v jsonb;aid uuid:=gen_random_uuid();old hr_private.sick_leave_cases%rowtype;
begin
 perform 1 from hr_private.firms where company_id=p_company_id for update;
 e:=hr_private.conversation_employee(p_company_id,p_employee_id);
 if auth.uid() is distinct from e.leader_id then raise exception 'Nærmeste leder starter samtalen.' using errcode='42501';end if;
 if p_employee_revision is distinct from e.revision then raise exception 'Medarbeiderens tilgang er endret.' using errcode='40001';end if;
 if p_conversation_id is null or p_on is null or p_on>(now() at time zone 'Europe/Oslo')::date or p_on<'1000-01-01'::date or p_on>'9998-06-01'::date or p_mode is null or p_mode not in('full','partial') then raise exception 'Samtaleidentitet og dato kreves.' using errcode='22023';end if;
 select * into old from hr_private.sick_leave_cases where id=p_conversation_id;
 if old.id is not null then
  if old.company_id<>p_company_id or old.employee_id<>e.id then raise exception 'Oppfølgingen er ikke tilgjengelig.' using errcode='42501';end if;
  -- Unknown start responses are resolved by reading this ID, never by creating another case.
  return public.hr_sick_leave_get(p_company_id,e.id,old.id);
 end if;
 if exists(select 1 from hr_private.sick_leave_cases c join hr_private.artifacts a on a.id=c.current_artifact_id where c.company_id=p_company_id and c.employee_id=e.id and a.payload->>'case_status'='active') then raise exception 'Åpne den aktive oppfølgingen først.' using errcode='22023';end if;
 select * into t from hr_private.conversation_templates where company_id=p_company_id and id=p_template_id;
 if t.id is null or t.archived then raise exception 'Velg en aktiv samtalemal.' using errcode='22023';end if;
 if t.revision is distinct from p_template_revision then raise exception 'Malen er endret. Velg ny utgave.' using errcode='40001';end if;
 select content into tpl from hr_private.conversation_template_versions where template_id=t.id and revision=t.revision;
 if tpl->>'kind'<>'sickleave' then raise exception 'Velg en sykefraværsmal.' using errcode='22023';end if;
 if(select count(*) from hr_private.sick_leave_cases where company_id=p_company_id and employee_id=e.id)>=200 then
  raise exception 'Kontroller lagringsbehovet før flere samtaler opprettes.' using errcode='22023';end if;
 v:=jsonb_build_object('type','sickleave','id',p_conversation_id,'revision',1,'content_version',1,
 'template_id',t.id,'template_revision',t.revision,'template',tpl,'leader_id',e.leader_id,'on',p_on,'stage','preparation','shared',false,
 'preparation','{}'::jsonb,'meeting','{}'::jsonb,'actions','[]'::jsonb,'next_on','',
 'comments',jsonb_build_object('employee','','leader',''),'confirmations',jsonb_build_object('employee',null,'leader',null),
 'case_status','active','absence_mode',p_mode,'returned_on','','milestones',jsonb_build_object('plan',jsonb_build_object('status','open','on','','note',''),'meeting1',jsonb_build_object('status',case when p_mode='partial' then 'review' else 'open' end,'on','','note',''),'activity',jsonb_build_object('status','open','on','','note',''),'meeting2',jsonb_build_object('status','open','on','','note','')),'sharing',jsonb_build_object('sykmelder','[]'::jsonb,'nav','[]'::jsonb),
 'saved_at',now(),'saved_by',auth.uid());
 insert into hr_private.artifacts(id,company_id,employee_id,employee_revision,kind,payload,review_on)
 values(aid,p_company_id,e.id,e.revision,'version',v,(select review_on from hr_private.firms where company_id=p_company_id));
 insert into hr_private.sick_leave_cases values(p_conversation_id,p_company_id,e.id,1,aid);
 return public.hr_sick_leave_get(p_company_id,e.id,p_conversation_id);
end$function$

CREATE OR REPLACE FUNCTION public.hr_template_save(p_company_id uuid, p_template_id uuid, p_revision integer, p_content jsonb, p_archived boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x jsonb; t hr_private.conversation_templates%rowtype; old_content jsonb;
begin
 -- Same lock order as HR administration. Serializes first creation and quota too.
 perform 1 from hr_private.firms where company_id=p_company_id for update;
 x:=hr_private.require_context(p_company_id,true);
 if p_template_id is null or p_revision is null or p_revision<0 or p_archived is null then
  raise exception 'Malidentitet, revisjon og arkivvalg kreves.' using errcode='22023';
 end if;
 perform hr_private.validate_conversation_template(p_content);
 select * into t from hr_private.conversation_templates where id=p_template_id for update;
 if t.id is not null and t.company_id<>p_company_id then raise exception 'Malen er ikke tilgjengelig i firmaet.' using errcode='42501'; end if;
 if p_revision is distinct from coalesce(t.revision,0) then raise exception 'Malen er endret. Hent ny utgave før du lagrer.' using errcode='40001'; end if;
 if t.id is null then
  if p_archived then raise exception 'En ny mal kan ikke starte som arkivert.' using errcode='22023'; end if;
  if (select count(*) from hr_private.conversation_templates where company_id=p_company_id)>=50 then
   raise exception 'Firmaet har nådd grensen på 50 maler, inkludert arkiverte.' using errcode='22023';
  end if;
  insert into hr_private.conversation_templates(id,company_id,revision,archived) values(p_template_id,p_company_id,1,false) returning * into t;
 else
  select content into old_content from hr_private.conversation_template_versions where template_id=t.id and revision=t.revision;
  if old_content=p_content and t.archived=p_archived then return public.hr_template_get(p_company_id,t.id); end if;
  if t.archived and p_archived and old_content<>p_content then raise exception 'Gjenåpne malen før innholdet endres.' using errcode='22023'; end if;
  update hr_private.conversation_templates set revision=revision+1,archived=p_archived where id=t.id returning * into t;
 end if;
 insert into hr_private.conversation_template_versions(company_id,template_id,revision,content,archived,saved_by)
 values(p_company_id,t.id,t.revision,p_content,t.archived,auth.uid());
 perform hr_private.require_context(p_company_id,true);
 return public.hr_template_get(p_company_id,t.id);
end $function$

CREATE OR REPLACE FUNCTION public.kshms_acknowledge_batch(p_company_id uuid, p_user_id uuid, p_version_ids uuid[], p_statement text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 actor uuid := auth.uid();
 confirmed_at timestamptz;
 identity jsonb;
 inserted_count integer;
begin
 perform kshms_private.require_context(p_company_id);
 if actor is null or p_user_id is distinct from actor then
  raise exception 'Bekreftelse kan bare registreres på egen bruker.' using errcode='42501';
 end if;
 if p_statement is distinct from 'Jeg bekrefter at jeg har lest og forstått alle rutineutgavene i listen, forstår mitt ansvar og vil følge rutinene. Jeg ber om forklaring eller nødvendig opplæring dersom noe er uklart, og melder fra om farlige forhold og avvik. Bekreftelsen gjelder min egen gjennomgang av de oppførte utgavene; den erstatter ikke opplæring eller faktisk utførelse.' then
  raise exception 'Bekreft at alle oppførte rutineutgaver er lest og forstått.' using errcode='22023';
 end if;
 if p_version_ids is null or coalesce(pg_catalog.array_ndims(p_version_ids),0)<>1
  or pg_catalog.cardinality(p_version_ids) not between 1 and 500
  or exists(select 1 from pg_catalog.unnest(p_version_ids) id where id is null)
  or (select count(distinct id) from pg_catalog.unnest(p_version_ids) id)<>pg_catalog.cardinality(p_version_ids) then
  raise exception 'En entydig liste med 1 til 500 rutineutgaver kreves.' using errcode='22023';
 end if;
 -- Same serialization boundary as the existing publication/access commands.
 perform 1 from public.company_module_access
 where company_id=p_company_id and module_key='kshms' for update;
 perform kshms_private.require_context(p_company_id);
 if auth.uid() is distinct from actor then
  raise exception 'Brukeren er endret.' using errcode='42501';
 end if;
 if exists(
  select 1 from pg_catalog.unnest(p_version_ids) requested(id)
  where not exists(
   select 1 from public.kshms_assignments a
   join public.kshms_versions v on v.company_id=a.company_id and v.id=a.version_id
   join public.kshms_routines r on r.company_id=v.company_id and r.id=v.routine_id
   where a.company_id=p_company_id and a.user_id=actor and a.version_id=requested.id and not r.archived
  )
 ) then
  raise exception 'En oppført utgave er ikke lenger aktiv og tildelt deg.' using errcode='42501';
 end if;
 -- New assignments/editions must be presented and read before new consent.
 if exists(
  select 1 from public.kshms_assignments a
  join public.kshms_versions v on v.company_id=a.company_id and v.id=a.version_id
  join public.kshms_routines r on r.company_id=v.company_id and r.id=v.routine_id
  left join public.kshms_acknowledgments ack on ack.version_id=a.version_id and ack.user_id=a.user_id
  where a.company_id=p_company_id and a.user_id=actor and not r.archived
  and ack.version_id is null and not (a.version_id=any(p_version_ids))
 ) then
  raise exception 'Listen over rutineutgaver er endret. Les nye utgaver og bekreft den oppdaterte listen.' using errcode='40001';
 end if;
 confirmed_at:=pg_catalog.clock_timestamp();
 identity:=kshms_private.identity_snapshot(actor);
 with inserted as (
  insert into public.kshms_acknowledgments(company_id,version_id,user_id,acknowledged_at,statement,user_identity)
  select p_company_id,id,actor,confirmed_at,p_statement,identity from pg_catalog.unnest(p_version_ids) id
  on conflict (version_id,user_id) do nothing returning version_id
 ), audited as (
  insert into public.kshms_audit(company_id,actor_id,action,object_id,at)
  select p_company_id,actor,'ack_batch',version_id,confirmed_at from inserted returning object_id
 ) select count(*) into inserted_count from audited;
 return pg_catalog.jsonb_build_object('inserted_count',inserted_count,'version_count',pg_catalog.cardinality(p_version_ids),'acknowledged_at',confirmed_at);
end $function$

CREATE OR REPLACE FUNCTION public.kshms_checklist_command(p_company_id uuid, p_action text, p_request_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x jsonb; t public.kshms_checklist_templates%rowtype; v public.kshms_checklist_versions%rowtype; receipt public.kshms_checklist_commands%rowtype;
 content jsonb; snapshot jsonb; content_hash text; payload_hash text; template_id uuid; result jsonb;
begin
 x:=kshms_private.require_context(p_company_id,true,p_action='publish');
 perform 1 from public.company_module_access where company_id=p_company_id and module_key='kshms' for update;
 x:=kshms_private.require_context(p_company_id,true,p_action='publish');
 if p_request_id is null or p_action not in ('save','publish','archive') or jsonb_typeof(p_payload) is distinct from 'object' then raise exception 'Invalid checklist command'; end if;
 payload_hash:=encode(sha256(convert_to(p_action||p_payload::text,'UTF8')),'hex');
 select * into receipt from public.kshms_checklist_commands where company_id=p_company_id and request_id=p_request_id;
 if found then
  if receipt.actor_id<>auth.uid() or receipt.payload_hash<>payload_hash then raise exception 'Request reused with different content' using errcode='40001'; end if;
  return receipt.result;
 end if;
 template_id:=(p_payload->>'id')::uuid;
 if template_id is null then raise exception 'Missing checklist id'; end if;
 select * into t from public.kshms_checklist_templates where id=template_id and company_id=p_company_id for update;
 if not found then
  if p_action='archive' or coalesce((p_payload->>'revision')::bigint,-1)<>0 then raise exception 'Sjekklisten er endret. Oppdater og sammenlign teksten.' using errcode='40001'; end if;
  content:=kshms_private.checklist_content(p_payload->'content');
  perform kshms_private.checklist_snapshot(p_company_id,template_id,content);
  insert into public.kshms_checklist_templates(id,company_id,draft,created_by,updated_by) values(template_id,p_company_id,content,auth.uid(),auth.uid()) returning * into t;
 else
  if t.archived or t.revision<>coalesce((p_payload->>'revision')::bigint,-1) then raise exception 'Sjekklisten er endret eller arkivert. Oppdater og sammenlign teksten.' using errcode='40001'; end if;
  if p_action='archive' then
   update public.kshms_checklist_templates set archived=true,revision=revision+1,updated_by=auth.uid(),updated_at=now() where id=t.id returning * into t;
  else
   content:=kshms_private.checklist_content(p_payload->'content');
   perform kshms_private.checklist_snapshot(p_company_id,template_id,content);
   update public.kshms_checklist_templates set draft=content,revision=revision+1,updated_by=auth.uid(),updated_at=now() where id=t.id returning * into t;
  end if;
 end if;
 if p_action='publish' then
  snapshot:=kshms_private.checklist_snapshot(p_company_id,t.id,content);
  content_hash:=encode(sha256(convert_to(snapshot::text,'UTF8')),'hex');
  select * into v from public.kshms_checklist_versions cv where cv.company_id=p_company_id and cv.template_id=t.id order by cv.number desc limit 1;
  if v.id is null or v.content_hash<>content_hash then
   insert into public.kshms_checklist_versions(company_id,template_id,number,content,content_hash,published_by,published_identity)
   values(p_company_id,t.id,coalesce(v.number,0)+1,snapshot,content_hash,auth.uid(),kshms_private.identity_snapshot(auth.uid())) returning * into v;
  end if;
 end if;
 result:=jsonb_build_object('template',to_jsonb(t),'version',case when v.id is null then null else to_jsonb(v) end);
 insert into public.kshms_checklist_commands(company_id,request_id,actor_id,payload_hash,result) values(p_company_id,p_request_id,auth.uid(),payload_hash,result);
 insert into public.kshms_audit(company_id,actor_id,action,object_id) values(p_company_id,auth.uid(),'checklist-'||p_action,t.id);
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.kshms_command(p_company_id uuid, p_action text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x jsonb; r public.kshms_routines%rowtype; v public.kshms_versions%rowtype; s public.kshms_settings%rowtype;
 target uuid; enabled boolean; access_role text; next_date date; result jsonb:='{}'; object_id uuid;
begin
 x:=kshms_private.require_context(p_company_id,p_action<>'ack',p_action='publish');
 -- Serialize firm permission/assignment/settings changes and snapshots, including activation races.
 perform 1 from public.company_module_access where company_id=p_company_id and module_key='kshms' for update;
 x:=kshms_private.require_context(p_company_id,p_action<>'ack',p_action='publish');
 if p_action in ('access','archive') and not coalesce((x->>'administer')::boolean,false) then raise exception 'Firmaadmin required for member access or archiving' using errcode='42501'; end if;
 if p_action='access' then
  target:=(p_payload->>'user_id')::uuid; enabled:=(p_payload->>'enabled')::boolean; access_role:=p_payload->>'role';
  if enabled is null or access_role not in ('reader','responsible') or not exists(select 1 from public.sales_company_memberships m join public.profiles p on p.id=m.user_id where m.company_id=p_company_id and m.user_id=target and p.approved and not coalesce(p.deactivated,false) and p.role in ('admin','member','ansatt','firmaadmin')) then raise exception 'Invalid internal member'; end if;
  insert into public.kshms_member_access(company_id,user_id,role,enabled,changed_by) values(p_company_id,target,access_role,enabled,auth.uid())
  on conflict(company_id,user_id) do update set role=excluded.role,enabled=excluded.enabled,changed_by=excluded.changed_by,changed_at=now();
  object_id:=target;
 elsif p_action='settings' then
  select * into s from public.kshms_settings where company_id=p_company_id for update;
  if coalesce(s.revision,0)<>coalesce((p_payload->>'revision')::bigint,0) then raise exception 'Settings changed; reload' using errcode='40001'; end if;
  target:=(p_payload->>'responsible_user_id')::uuid;
  if not (x->>'administer')::boolean and (s.company_id is null or s.responsible_user_id is distinct from target) then raise exception 'Firmaadmin appoints KS/HMS responsible' using errcode='42501'; end if;
  if not exists(select 1 from public.sales_company_memberships m join public.profiles p on p.id=m.user_id left join public.kshms_member_access a on a.company_id=m.company_id and a.user_id=m.user_id where m.company_id=p_company_id and m.user_id=target and p.approved and not coalesce(p.deactivated,false) and p.role in ('admin','member','ansatt','firmaadmin') and (m.workspace_role='firmaadmin' or (a.enabled and a.role='responsible'))) then raise exception 'Choose a company admin or an enabled KS/HMS responsible'; end if;
  if jsonb_typeof(p_payload->'trades') is distinct from 'array' or jsonb_array_length(p_payload->'trades')=0 or exists(select 1 from jsonb_array_elements_text(p_payload->'trades') t where t not in ('mur_flis','tomrer','maler','vvs')) then raise exception 'Choose supported trades'; end if;
  insert into public.kshms_settings(company_id,trades,activities,responsibilities,risks,responsible_user_id,updated_by)
  values(p_company_id,array(select jsonb_array_elements_text(p_payload->'trades')),coalesce(p_payload->>'activities',''),coalesce(p_payload->>'responsibilities',''),coalesce(p_payload->>'risks',''),target,auth.uid())
  on conflict(company_id) do update set revision=public.kshms_settings.revision+1,trades=excluded.trades,activities=excluded.activities,responsibilities=excluded.responsibilities,risks=excluded.risks,responsible_user_id=excluded.responsible_user_id,updated_by=excluded.updated_by,updated_at=now();
 elsif p_action='save' then
  perform kshms_private.validate_draft(p_payload->'draft');
  object_id:=nullif(p_payload->>'id','')::uuid;
  if object_id is null then
   insert into public.kshms_routines(company_id,draft,created_by,updated_by) values(p_company_id,p_payload->'draft',auth.uid(),auth.uid()) returning * into r;
  else
   select * into r from public.kshms_routines where id=object_id and company_id=p_company_id for update;
   if r.id is null or r.revision<>coalesce((p_payload->>'revision')::bigint,-1) then raise exception 'Routine changed; reload before saving' using errcode='40001'; end if;
   if r.archived then raise exception 'Archived routine: copy it to create a new draft'; end if;
   update public.kshms_routines set draft=p_payload->'draft',revision=revision+1,updated_by=auth.uid(),updated_at=now() where id=r.id returning * into r;
  end if;
  object_id:=r.id; result:=to_jsonb(r);
 elsif p_action in ('publish','archive') then
  object_id:=(p_payload->>'id')::uuid;
  select * into r from public.kshms_routines where id=object_id and company_id=p_company_id for update;
  if r.id is null or r.revision<>coalesce((p_payload->>'revision')::bigint,-1) then raise exception 'Routine changed; reload' using errcode='40001'; end if;
  if p_action='archive' then
   update public.kshms_routines set archived=true,revision=revision+1,updated_by=auth.uid(),updated_at=now() where id=r.id;
  else
   if r.archived then raise exception 'Archived routine'; end if;
   perform kshms_private.validate_draft(r.draft);
   if length(trim(coalesce(p_payload->>'change_summary','')))<5 then raise exception 'Explain the publication/change'; end if;
   if not exists(select 1 from public.kshms_settings where company_id=p_company_id) then raise exception 'Complete company setup first'; end if;
   if p_payload ? 'acknowledge_self' and jsonb_typeof(p_payload->'acknowledge_self') is distinct from 'boolean' then raise exception 'Explicit own confirmation must be a boolean'; end if;
   if coalesce((p_payload->>'acknowledge_self')::boolean,false) and p_payload->>'self_statement' is distinct from 'Jeg har gjennomgått denne rutineversjonen, forstår mitt ansvar og vil følge rutinen. Jeg ber om forklaring eller nødvendig opplæring dersom noe er uklart, og melder fra om farlige forhold og avvik. Bekreftelsen dokumenterer gjennomgang; den erstatter ikke opplæring eller faktisk utførelse.' then raise exception 'Own confirmation statement required'; end if;
   insert into public.kshms_versions(company_id,routine_id,number,content,content_hash,change_summary,published_by,requires_ack,publisher_identity)
   select p_company_id,r.id,coalesce(max(number),0)+1,r.draft,encode(sha256(convert_to(r.draft::text,'UTF8')),'hex'),p_payload->>'change_summary',auth.uid(),coalesce(max(number),0)=0 or coalesce((p_payload->>'requires_ack')::boolean,true),kshms_private.identity_snapshot(auth.uid()) from public.kshms_versions where routine_id=r.id returning * into v;
   -- Initial/significant versions require fresh acknowledgments; old records remain immutable.
   insert into public.kshms_assignments(company_id,version_id,user_id,assigned_by)
   select p_company_id,v.id,m.user_id,auth.uid() from public.sales_company_memberships m join public.profiles p on p.id=m.user_id
   left join public.kshms_member_access a on a.company_id=m.company_id and a.user_id=m.user_id
   where m.company_id=p_company_id and p.approved and not coalesce(p.deactivated,false) and p.role in ('admin','member','ansatt','firmaadmin')
   and (m.workspace_role='firmaadmin' or a.enabled);
   if coalesce((p_payload->>'acknowledge_self')::boolean,false) then
    if not exists(select 1 from public.kshms_assignments where company_id=p_company_id and version_id=v.id and user_id=auth.uid()) then raise exception 'Published version not assigned to publisher' using errcode='42501'; end if;
    insert into public.kshms_acknowledgments(company_id,version_id,user_id,statement,user_identity) values(p_company_id,v.id,auth.uid(),p_payload->>'self_statement',v.publisher_identity);
    insert into public.kshms_audit(company_id,actor_id,action,object_id) values(p_company_id,auth.uid(),'ack',v.id);
   end if;
   update public.kshms_routines set revision=revision+1,updated_at=now(),updated_by=auth.uid() where id=r.id;
   result:=to_jsonb(v);
  end if;
 elsif p_action='assign' then
  object_id:=(p_payload->>'version_id')::uuid; target:=(p_payload->>'user_id')::uuid;
  if not exists(select 1 from public.kshms_versions dbv join public.kshms_routines dbr on dbr.id=dbv.routine_id where dbv.company_id=p_company_id and dbv.id=object_id and not dbr.archived) or not exists(select 1 from public.sales_company_memberships m join public.profiles p on p.id=m.user_id left join public.kshms_member_access a on a.company_id=m.company_id and a.user_id=m.user_id where m.company_id=p_company_id and m.user_id=target and p.approved and not coalesce(p.deactivated,false) and p.role in ('admin','member','ansatt','firmaadmin') and (a.enabled or m.workspace_role='firmaadmin')) then raise exception 'Invalid assignment'; end if;
  insert into public.kshms_assignments(company_id,version_id,user_id,assigned_by) values(p_company_id,object_id,target,auth.uid()) on conflict do nothing;
 elsif p_action='ack' then
  object_id:=(p_payload->>'version_id')::uuid;
  if p_payload->>'statement' is distinct from 'Jeg har gjennomgått denne rutineversjonen, forstår mitt ansvar og vil følge rutinen. Jeg ber om forklaring eller nødvendig opplæring dersom noe er uklart, og melder fra om farlige forhold og avvik. Bekreftelsen dokumenterer gjennomgang; den erstatter ikke opplæring eller faktisk utførelse.' then raise exception 'Confirmation statement required'; end if;
  if not exists(select 1 from public.kshms_assignments a where a.company_id=p_company_id and a.user_id=auth.uid() and a.version_id=object_id) then raise exception 'Version not assigned to you' using errcode='42501'; end if;
  insert into public.kshms_acknowledgments(company_id,version_id,user_id,statement,user_identity) values(p_company_id,object_id,auth.uid(),p_payload->>'statement',kshms_private.identity_snapshot(auth.uid())) on conflict do nothing;
 elsif p_action='review' then
  if not coalesce((x->>'responsible')::boolean,false) then raise exception 'Designated KS/HMS responsible signs the annual review' using errcode='42501'; end if;
  next_date:=(p_payload->>'next_review_on')::date;
  if next_date is null or next_date<=current_date or next_date>(current_date+interval '1 year')::date or length(trim(coalesce(p_payload->>'findings','')))<10 or length(trim(coalesce(p_payload->>'follow_up','')))<10 then raise exception 'Review findings, follow-up and next date (within one year) required'; end if;
  if not exists(select 1 from public.kshms_versions dbv join public.kshms_routines dbr on dbr.id=dbv.routine_id where dbv.company_id=p_company_id and not dbr.archived) then raise exception 'No active published handbook to review'; end if;
  if coalesce((p_payload->>'settings_revision')::bigint,-1)<>(select revision from public.kshms_settings where company_id=p_company_id) or coalesce(p_payload->'version_snapshot','null')<>(select coalesce(jsonb_agg(jsonb_build_object('id',dbv.id,'hash',dbv.content_hash) order by dbv.id),'[]') from public.kshms_versions dbv join public.kshms_routines dbr on dbr.id=dbv.routine_id where dbv.company_id=p_company_id and not dbr.archived and dbv.number=(select max(number) from public.kshms_versions where routine_id=dbv.routine_id)) then raise exception 'Handbook changed during review; reload' using errcode='40001'; end if;
  insert into public.kshms_reviews(company_id,signed_by,version_snapshot,findings,follow_up,next_review_on,statement)
  values(p_company_id,auth.uid(),p_payload->'version_snapshot',p_payload->>'findings',p_payload->>'follow_up',next_date,'Jeg har gjennomgått de oppførte rutineversjonene, vurdert relevans, endringer og etterlevelse, og registrert funn og videre oppfølging. Revisjonen er ikke en godkjenning fra myndighetene.') returning id into object_id;
  update public.kshms_settings set next_review_on=next_date,revision=revision+1,updated_at=now(),updated_by=auth.uid() where company_id=p_company_id;
 else raise exception 'Unsupported KS/HMS action'; end if;
 insert into public.kshms_audit(company_id,actor_id,action,object_id) values(p_company_id,auth.uid(),p_action,object_id);
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.kshms_deviation_command(p_company_id uuid, p_action text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare x jsonb;d public.kshms_deviations%rowtype;old_d public.kshms_deviations%rowtype;p public.projects%rowtype;
 target uuid;handler uuid;project_id uuid;object_id uuid;source_kind text;source_key text;source_group text;source_item text;source_snapshot jsonb;new_status text;event_action text;
begin
 x:=kshms_private.require_context(p_company_id);
 if jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>100000 then raise exception 'Invalid case payload';end if;
 -- Lock in the same order as activation/member commands. Recheck on the lock.
 perform 1 from public.company_module_access where company_id=p_company_id and module_key='kshms' for update;
 x:=kshms_private.require_context(p_company_id);
 if p_action='create' then
  select * into d from public.kshms_deviations where company_id=p_company_id and created_by=auth.uid() and request_id=(p_payload->>'request_id')::uuid;
  if d.id is not null then return to_jsonb(d);end if;
  target:=(p_payload->>'responsible_id')::uuid;handler:=coalesce(nullif(p_payload->>'handler_id','')::uuid,target);
  if not kshms_private.deviation_member(p_company_id,target) or not kshms_private.deviation_member(p_company_id,handler) then raise exception 'Choose an active employee with KS/HMS access' using errcode='42501';end if;
  project_id:=nullif(p_payload->>'project_id','')::uuid;
  source_kind:=coalesce(p_payload->>'source_kind','company');source_key:=nullif(p_payload->>'source_key','');
  if project_id is not null then
   select * into p from public.projects where id=project_id and company_scope_id=p_company_id for update;
   if p.id is null or not public.project_row_access_allowed(p.company_scope_id,p.user_id) then raise exception 'Project access denied' using errcode='42501';end if;
   if p.locked or coalesce((p.data#>>'{project,locked}')::boolean,false) then raise exception 'Unlock the project before changing a linked deviation';end if;
  end if;
  if source_kind='project' then
   select e into source_snapshot from jsonb_array_elements(coalesce(p.data#>'{project,projectDeviations}','[]')) e where e->>'id'=source_key;
   if source_snapshot is null or coalesce(source_snapshot->>'status','Åpent')='Lukket' then raise exception 'Save an open project deviation before linking it';end if;
  elsif source_kind='checklist' then
   source_group:=nullif(p_payload->>'source_group','');source_item:=nullif(p_payload->>'source_item','');
   source_key:=jsonb_build_array(source_group,source_item)::text;
   source_snapshot:=p.data#>array['checklist',source_group,source_item];
   if source_snapshot is null or source_snapshot->>'status' is distinct from 'Avvik' then raise exception 'Save an open checklist deviation before linking it';end if;
  elsif source_kind<>'company' then raise exception 'Invalid source type';
  end if;
  if source_kind<>'company' then
   select * into d from public.kshms_deviations where company_id=p_company_id and kshms_deviations.project_id=project_id and kshms_deviations.source_kind=source_kind and kshms_deviations.source_key=source_key;
   if d.id is not null then
    if not kshms_private.deviation_visible(d,x) then raise exception 'Case access denied' using errcode='42501';end if;
    return to_jsonb(d);
   end if;
  end if;
  insert into public.kshms_deviations(company_id,request_id,title,event,category,immediate_action,responsible_id,handler_id,responsible_identity,handler_identity,due_on,project_id,source_kind,source_key,source_group,source_item,source_snapshot,created_by,creator_identity,project_reference,routines)
  values(p_company_id,(p_payload->>'request_id')::uuid,trim(p_payload->>'title'),trim(p_payload->>'event'),p_payload->>'category',coalesce(p_payload->>'immediate_action',''),target,handler,kshms_private.identity_snapshot(target),kshms_private.identity_snapshot(handler),(p_payload->>'due_on')::date,project_id,source_kind,source_key,source_group,source_item,source_snapshot,auth.uid(),kshms_private.identity_snapshot(auth.uid()),coalesce(p_payload->>'project_reference',''),coalesce(p_payload->>'routines','')) returning * into d;
  event_action:='create';
 elsif p_action in ('save','close','reopen') then
  object_id:=(p_payload->>'id')::uuid;
  -- Project lock precedes case lock in both create/update, avoiding a reverse lock order.
  select * into d from public.kshms_deviations where id=object_id and company_id=p_company_id;
  if d.id is null or not kshms_private.deviation_visible(d,x) then raise exception 'Case access denied' using errcode='42501';end if;
  if d.project_id is not null then
   if d.source_kind='company' then perform kshms_private.project_checklist_access(p_company_id,d.project_id,true); end if;
   select * into p from public.projects where id=d.project_id for update;
   if p.locked or coalesce((p.data#>>'{project,locked}')::boolean,false) then raise exception 'Unlock the project before changing a linked deviation';end if;
  end if;
  select * into d from public.kshms_deviations where id=object_id and company_id=p_company_id for update;
  if d.revision is distinct from (p_payload->>'revision')::bigint then raise exception 'Case changed; reload before saving' using errcode='40001';end if;
  if not (x->>'manage')::boolean and d.responsible_id<>auth.uid() then raise exception 'Assigned responsible or KS/HMS manager required' using errcode='42501';end if;
  if p_action='close' and d.responsible_id<>auth.uid() then raise exception 'Only the assigned responsible can close this case' using errcode='42501';end if;
  if d.status='closed' and p_action<>'reopen' then raise exception 'Closed case: reopen explicitly before editing';end if;
  old_d:=d;
  if p_action='reopen' then
   if not (x->>'manage')::boolean then raise exception 'KS/HMS manager required for reopening' using errcode='42501';end if;
   if d.status<>'closed' or length(trim(coalesce(p_payload->>'reason','')))<10 then raise exception 'Explain why the closed case is reopened';end if;
   target:=coalesce(nullif(p_payload->>'responsible_id','')::uuid,d.responsible_id);
   if not kshms_private.deviation_member(p_company_id,target) then raise exception 'Choose an active employee with KS/HMS access' using errcode='42501';end if;
   update public.kshms_deviations set status='open',responsible_id=target,
    responsible_identity=case when target<>responsible_id then kshms_private.identity_snapshot(target) else responsible_identity end,
    due_on=coalesce((p_payload->>'due_on')::date,due_on),closed_by=null,closed_identity=null,closed_at=null,control_note='',
    revision=revision+1,assignment_number=assignment_number+1,updated_at=now(),follow_up=follow_up||E'\nGjenåpnet: '||trim(p_payload->>'reason') where id=d.id returning * into d;
  else
   target:=coalesce(nullif(p_payload->>'responsible_id','')::uuid,d.responsible_id);handler:=coalesce(nullif(p_payload->>'handler_id','')::uuid,d.handler_id);
   if (target<>d.responsible_id or handler<>d.handler_id) and not (x->>'manage')::boolean then raise exception 'KS/HMS manager required for reassignment' using errcode='42501';end if;
   if (target<>d.responsible_id and not kshms_private.deviation_member(p_company_id,target)) or (handler<>d.handler_id and not kshms_private.deviation_member(p_company_id,handler)) then raise exception 'Choose an active employee with KS/HMS access' using errcode='42501';end if;
   new_status:=case when p_action='close' then 'closed' else coalesce(p_payload->>'status','in_progress') end;
   if p_action='save' and new_status not in('open','in_progress') then raise exception 'Use explicit controlled closure';end if;
   if p_action='close' then
    if jsonb_typeof(p_payload->'controlled') is distinct from 'boolean' or p_payload->>'controlled'<>'true'
     or length(trim(coalesce(p_payload->>'improvement_action','')))<1 or length(trim(coalesce(p_payload->>'control_note','')))<1
     or length(trim(coalesce(p_payload->>'cause','')))<1 then raise exception 'Document cause, completed measures and checked result before closure';end if;
   end if;
   update public.kshms_deviations set title=coalesce(trim(p_payload->>'title'),title),event=coalesce(trim(p_payload->>'event'),event),category=coalesce(p_payload->>'category',category),
    project_reference=coalesce(p_payload->>'project_reference',project_reference),routines=coalesce(p_payload->>'routines',routines),
    cause=coalesce(p_payload->>'cause',cause),immediate_action=coalesce(p_payload->>'immediate_action',immediate_action),improvement_action=coalesce(p_payload->>'improvement_action',improvement_action),follow_up=coalesce(p_payload->>'follow_up',follow_up),
    responsible_id=target,handler_id=handler,responsible_identity=case when target<>responsible_id then kshms_private.identity_snapshot(target) else responsible_identity end,
    handler_identity=case when handler<>handler_id then kshms_private.identity_snapshot(handler) else handler_identity end,due_on=coalesce((p_payload->>'due_on')::date,due_on),
    status=new_status,include_in_report=coalesce((p_payload->>'include_in_report')::boolean,include_in_report),
    control_note=case when p_action='close' then trim(p_payload->>'control_note') else coalesce(p_payload->>'control_note',control_note) end,
    closed_by=case when p_action='close' then auth.uid() else null end,closed_identity=case when p_action='close' then kshms_private.identity_snapshot(auth.uid()) else null end,
    closed_at=case when p_action='close' then now() else null end,revision=revision+1,assignment_number=assignment_number+case when target<>responsible_id then 1 else 0 end,updated_at=now()
   where id=d.id returning * into d;
  end if;
  event_action:=p_action;
 else raise exception 'Unsupported deviation action';end if;
 insert into public.kshms_deviation_events(company_id,deviation_id,actor_id,actor_identity,action,snapshot)
 values(p_company_id,d.id,auth.uid(),kshms_private.identity_snapshot(auth.uid()),event_action,to_jsonb(d));
 if d.status<>'closed' and (event_action in('create','reopen') or d.responsible_id is distinct from old_d.responsible_id) then
  insert into public.kshms_notification_outbox(company_id,deviation_id,user_id,assignment_number) values(p_company_id,d.id,d.responsible_id,d.assignment_number) on conflict do nothing;
 end if;
 if d.project_id is not null and d.source_kind<>'company' then update public.projects set data=data where id=d.project_id;end if;
 return to_jsonb(d);
end $function$

CREATE OR REPLACE FUNCTION public.kshms_execution_command(p_company_id uuid, p_action text, p_request_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare x jsonb;e public.kshms_executions%rowtype;receipt public.kshms_execution_commands%rowtype;version_row public.kshms_checklist_versions%rowtype;p public.projects%rowtype;id uuid;project uuid;version uuid;kind text;c jsonb;target uuid;digest text;statement_value text:='Jeg bekrefter at jeg har gjennomført og kontrollert dokumentasjonen sammen med de oppgitte deltakerne.';point jsonb;answer jsonb;risk jsonb;cases jsonb;case_row jsonb;response jsonb;prefix jsonb:='[]';vals jsonb;
begin
 x:=kshms_private.require_context(p_company_id);
 if p_action is null or p_action not in('save','complete') or p_request_id is null or jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>3500000 then raise exception 'Ugyldig lagringsforespørsel.';end if;
 perform 1 from public.company_module_access where company_id=p_company_id and module_key='kshms' for update;x:=kshms_private.require_context(p_company_id);
 id:=(p_payload->>'id')::uuid;kind:=p_payload->>'kind';project:=nullif(p_payload->>'project_id','')::uuid;version:=nullif(p_payload->>'template_version_id','')::uuid;
 if id is null or kind not in('round','risk') then raise exception 'Ugyldig gjennomføring.';end if;
 if project is not null then p:=kshms_private.project_checklist_access(p_company_id,project,true);end if;
 digest:=encode(extensions.digest(convert_to(jsonb_build_object('action',p_action,'payload',p_payload)::text,'UTF8'),'sha256'),'hex');
 select * into receipt from public.kshms_execution_commands where company_id=p_company_id and request_id=p_request_id;
 if receipt.request_id is not null then if receipt.actor_id<>auth.uid() or receipt.payload_hash<>digest then raise exception 'Forespørselen er brukt med annen tekst eller bruker.' using errcode='40001';end if;return receipt.result;end if;
 select * into e from public.kshms_executions where kshms_executions.id=id and company_id=p_company_id for update;
 if e.id is not null then
  if not kshms_private.execution_visible(e,x) then raise exception 'Gjennomføringen er ikke tilgjengelig.' using errcode='42501';end if;
  if e.status='completed' then raise exception 'Fullført dokumentasjon kan ikke endres. Start en ny gjennomføring.' using errcode='42501';end if;
  if e.revision is distinct from (p_payload->>'revision')::bigint then raise exception 'En annen person har lagret endringer. Sammenlign med lagret utgave.' using errcode='40001';end if;
  if row(e.kind,e.project_id,e.template_version_id) is distinct from row(kind,project,version) then raise exception 'Prosjekt og malutgave er faste etter første lagring.';end if;
 else
  if (p_payload->>'revision')::bigint is distinct from 0::bigint or exists(select 1 from public.kshms_executions existing where existing.id=id) then raise exception 'Gjennomføringen er ikke tilgjengelig.' using errcode='42501';end if;
  if version is not null then
   if kind<>'round' then raise exception 'Risikovurdering bruker egne jobbspesifikke farer.';end if;
   select v.* into version_row from public.kshms_checklist_versions v join public.kshms_checklist_templates t on t.id=v.template_id and not t.archived where v.id=version and v.company_id=p_company_id;
   if version_row.id is null then raise exception 'Velg en tilgjengelig publisert firmamal.' using errcode='42501';end if;
   e.template_snapshot:=jsonb_build_object('id',version_row.id,'template_id',version_row.template_id,'number',version_row.number,'content_hash',version_row.content_hash,'content',version_row.content);
  end if;
 end if;
 c:=kshms_private.execution_content(p_payload->'content',kind,p_action='complete');
 if version is not null and c->'points' is distinct from e.template_snapshot#>'{content,points}' then raise exception 'En publisert malutgave kan ikke omskrives i gjennomføringen.';end if;
 target:=nullif(c->>'responsible_id','')::uuid;if not kshms_private.deviation_member(p_company_id,target) then raise exception 'Velg en aktiv ansvarlig med KS/HMS-tilgang.' using errcode='42501';end if;
 if kind='round' then
  for point in select value from jsonb_array_elements(c->'points') loop
   answer:=c->'answers'->(point->>'id');prefix:=kshms_private.checklist_prefix_add(prefix,point,answer);
   if point ? 'fields' then vals:=kshms_private.checklist_sign_values(point->'fields',answer->'values',coalesce(e.content->'answers'->(point->>'id')->'values','{}'),prefix);c:=jsonb_set(c,array['answers',point->>'id','values'],vals);end if;
  end loop;
 end if;
 if p_action='complete' and (target<>auth.uid() or p_payload->'confirmed' is distinct from 'true'::jsonb or p_payload->>'statement' is distinct from statement_value) then raise exception 'Bare valgt ansvarlig kan fullføre med egen bekreftelse.' using errcode='42501';end if;
 if kind='round' then
  cases:=c->'answers';for point in select value from jsonb_array_elements(c->'points') loop answer:=cases->(point->>'id');
   if answer->>'responsible_id'<>'' then
    if not kshms_private.deviation_member(p_company_id,(answer->>'responsible_id')::uuid) then raise exception 'Velg en aktiv tiltaksansvarlig med KS/HMS-tilgang.' using errcode='42501';end if;
    answer:=answer||jsonb_build_object('responsible_identity',kshms_private.identity_snapshot((answer->>'responsible_id')::uuid));cases:=cases||jsonb_build_object(point->>'id',answer);
   end if;
  end loop;c:=c||jsonb_build_object('answers',cases);
 else
  cases:='[]';for risk in select value from jsonb_array_elements(c->'risks') loop
   if risk->>'owner_id'<>'' then if not kshms_private.deviation_member(p_company_id,(risk->>'owner_id')::uuid) then raise exception 'Velg en aktiv tiltaksansvarlig med KS/HMS-tilgang.' using errcode='42501';end if;risk:=risk||jsonb_build_object('owner_identity',kshms_private.identity_snapshot((risk->>'owner_id')::uuid));end if;cases:=cases||jsonb_build_array(risk);
  end loop;c:=c||jsonb_build_object('risks',cases);
 end if;
 if e.id is null then
  insert into public.kshms_executions(id,company_id,kind,project_id,template_version_id,template_snapshot,content,responsible_id,responsible_identity,created_by,creator_identity,updated_by,updated_identity)
  values(id,p_company_id,kind,project,version,e.template_snapshot,c,target,kshms_private.identity_snapshot(target),auth.uid(),kshms_private.identity_snapshot(auth.uid()),auth.uid(),kshms_private.identity_snapshot(auth.uid())) returning * into e;
 else update public.kshms_executions set content=c,responsible_id=target,responsible_identity=kshms_private.identity_snapshot(target),updated_by=auth.uid(),updated_identity=kshms_private.identity_snapshot(auth.uid()),updated_at=now(),revision=revision+1 where kshms_executions.id=e.id returning * into e;end if;
 if p_action='complete' then
  if kind='round' then for point in select value from jsonb_array_elements(c->'points') loop answer:=c->'answers'->(point->>'id');if answer->>'status'='deviation' then
   case_row:=public.kshms_deviation_command(p_company_id,'create',jsonb_build_object('request_id',gen_random_uuid(),'title',left('Kontrollavvik: '||(point->>'title'),160),'event','Fra vernerunde/kontroll «'||(c->>'title')||'», punkt «'||(point->>'title')||'».'||E'\n'||(answer->>'comment'),'category','hms','responsible_id',answer->>'responsible_id','due_on',answer->>'due_on','project_id',project,'source_kind','company','source_key','execution:'||e.id::text||':'||(point->>'id'),'immediate_action',''));
   insert into public.kshms_execution_deviations(execution_id,point_id,deviation_id,point_title) values(e.id,(point->>'id')::uuid,(case_row->>'id')::uuid,point->>'title');
  end if;end loop;end if;
  update public.kshms_executions set status='completed',completed_by=auth.uid(),completed_identity=kshms_private.identity_snapshot(auth.uid()),completed_at=now(),statement=statement_value where kshms_executions.id=e.id returning * into e;
 end if;
 response:=jsonb_build_object('record',jsonb_build_object('id',e.id,'company_id',e.company_id,'revision',e.revision,'status',e.status));insert into public.kshms_execution_commands(company_id,request_id,actor_id,payload_hash,result) values(p_company_id,p_request_id,auth.uid(),digest,response);return response;
end $function$

CREATE OR REPLACE FUNCTION public.kshms_progress_save(p_company_id uuid, p_id uuid, p_revision integer, p_title text, p_address text, p_reference text, p_plan jsonb, p_archived boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x jsonb;r kshms_private.progress_plans%rowtype;a jsonb;s jsonb;v date;begin
 x:=kshms_private.require_context(p_company_id,true);
 if p_id is null or p_revision is null or p_revision<0 or p_archived is null or p_title is null or length(btrim(p_title)) not between 1 and 160
 or p_address is null or length(p_address)>250 or p_reference is null or length(p_reference)>100
 or p_plan is null or jsonb_typeof(p_plan)<>'object' or pg_column_size(p_plan)>500000
 or p_plan->'version' is distinct from '1'::jsonb or jsonb_typeof(p_plan->'activities') is distinct from 'array'
 or coalesce(p_plan->'source','null')<>'null'::jsonb
 then raise exception 'Ugyldig fremdriftsplan.' using errcode='22023';end if;
 if jsonb_array_length(p_plan->'activities')>500 then raise exception 'Planen kan ha høyst 500 arbeidsoperasjoner.' using errcode='22023';end if;
 if exists(select 1 from jsonb_array_elements(p_plan->'activities') z group by z->>'id' having count(*)>1)
 then raise exception 'Arbeidsoperasjonene må ha ulike ID-er.' using errcode='22023';end if;
 for a in select value from jsonb_array_elements(p_plan->'activities') loop
  if jsonb_typeof(a)<>'object' or coalesce(length(btrim(a->>'id')),0) not between 1 and 120 or coalesce(length(btrim(a->>'title')),0) not between 1 and 200
  or length(coalesce(a->>'trade',''))>160 or length(coalesce(a->>'resource',''))>250
  or coalesce(a->>'status','') not in ('Ikke startet','Pågår','Avventer','Ferdig')
  or (coalesce(a->>'nsCode','')<>'' and (a->>'nsCode' !~ '^[2-7][0-9]{1,3}$' or coalesce(a->>'nsKind','') not in ('building','system')))
  or jsonb_typeof(a->'sessions') is distinct from 'array' then raise exception 'Ugyldig arbeidsoperasjon eller fagkode.' using errcode='22023';end if;
  if jsonb_array_length(a->'sessions')>1000 or exists(select 1 from jsonb_array_elements(a->'sessions') z group by z->>'id' having count(*)>1)
  then raise exception 'For mange eller doble arbeidsøkter.' using errcode='22023';end if;
  for s in select value from jsonb_array_elements(a->'sessions') loop
   if jsonb_typeof(s)<>'object' or coalesce(length(s->>'id'),0) not between 1 and 120 or coalesce(s->>'date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    or coalesce(s->>'startTime','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or coalesce(s->>'endTime','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    or s->>'endTime'<=s->>'startTime' or length(coalesce(s->>'note',''))>5000 then raise exception 'Arbeidsøkten må ha gyldig dato og fra–til-tid.' using errcode='22023';end if;
   begin v:=(s->>'date')::date;exception when others then raise exception 'Ugyldig dato.' using errcode='22023';end;
  end loop;
 end loop;
 select * into r from kshms_private.progress_plans where id=p_id for update;
 if found then
  if r.company_id<>p_company_id then raise exception 'Feil firma.' using errcode='42501';end if;
  if r.revision<>p_revision then raise exception 'Planen er endret i en annen økt. Kladden er beholdt; hent lagret plan før du fortsetter.' using errcode='40001';end if;
  update kshms_private.progress_plans set title=btrim(p_title),address=btrim(p_address),reference=btrim(p_reference),plan=p_plan,archived=p_archived,revision=revision+1,updated_by=auth.uid(),updated_at=now() where id=p_id;
 else
  if p_revision<>0 then raise exception 'Planen er endret eller fjernet.' using errcode='40001';end if;
  begin
   insert into kshms_private.progress_plans(id,company_id,title,address,reference,plan,archived,created_by,updated_by)
   values(p_id,p_company_id,btrim(p_title),btrim(p_address),btrim(p_reference),p_plan,p_archived,auth.uid(),auth.uid());
  exception when unique_violation then raise exception 'Planen er allerede opprettet. Hent den lagrede planen.' using errcode='40001';end;
 end if;
 insert into public.kshms_audit(company_id,actor_id,action,object_id) values(p_company_id,auth.uid(),'progress_plan_saved',p_id);
 return public.kshms_progress_get(p_company_id,p_id);
end $function$

CREATE OR REPLACE FUNCTION public.kshms_publish_batch(p_company_id uuid, p_user_id uuid, p_routines jsonb, p_assessment text, p_approval_statement text, p_requires_ack boolean, p_acknowledge_self boolean, p_self_statement text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();item jsonb;r public.kshms_routines%rowtype;
 previous public.kshms_versions%rowtype;v jsonb;result jsonb:='[]';summary text;
begin
 perform kshms_private.require_context(p_company_id,true,true);
 if actor is null or p_user_id is distinct from actor then raise exception 'Firmagodkjenning krever riktig egen bruker.' using errcode='42501';end if;
 if p_approval_statement is distinct from 'Jeg har gjennomgått alle de oppførte rutineutkastene og vurdert at innholdet er tilpasset firmaets arbeid, risikoer og ansvarsfordeling. Jeg godkjenner at disse utkastene publiseres som firmaets rutiner.'
 or length(trim(coalesce(p_assessment,''))) not between 5 and 1500
 or p_requires_ack is null or p_acknowledge_self is null then raise exception 'Vurdering og uttrykkelig firmagodkjenning kreves.' using errcode='22023';end if;
 if (p_acknowledge_self and p_self_statement is distinct from 'Jeg har gjennomgått denne rutineversjonen, forstår mitt ansvar og vil følge rutinen. Jeg ber om forklaring eller nødvendig opplæring dersom noe er uklart, og melder fra om farlige forhold og avvik. Bekreftelsen dokumenterer gjennomgang; den erstatter ikke opplæring eller faktisk utførelse.')
 or (not p_acknowledge_self and p_self_statement is not null) then raise exception 'Egen lesebekreftelse må velges særskilt.' using errcode='22023';end if;
 if jsonb_typeof(p_routines) is distinct from 'array' then raise exception 'Velg rutineutkast.' using errcode='22023';end if;
 if jsonb_array_length(p_routines) not between 1 and 500 or exists(
  select 1 from jsonb_array_elements(p_routines) a where jsonb_typeof(a) is distinct from 'object'
  or nullif(a->>'id','') is null or jsonb_typeof(a->'revision') is distinct from 'number'
  or jsonb_typeof(a->'next_number') is distinct from 'number' or jsonb_typeof(a->'draft') is distinct from 'object'
 ) then raise exception 'Entydige lagrede rutineutkast kreves.' using errcode='22023';end if;
 if (select count(distinct (a->>'id')::uuid) from jsonb_array_elements(p_routines) a)<>jsonb_array_length(p_routines) then raise exception 'Samme rutine er valgt flere ganger.' using errcode='22023';end if;
 perform 1 from public.company_module_access where company_id=p_company_id and module_key='kshms' for update;
 perform kshms_private.require_context(p_company_id,true,true);
 -- Validate the complete frozen selection before the first canonical write.
 for item in select value from jsonb_array_elements(p_routines) order by value->>'id' loop
  select * into r from public.kshms_routines where company_id=p_company_id and id=(item->>'id')::uuid for update;
  if r.id is null then raise exception 'Rutinen tilhører ikke dette firmaet.' using errcode='42501';end if;
  select * into previous from public.kshms_versions where routine_id=r.id order by number desc limit 1;
  if r.archived or r.revision is distinct from (item->>'revision')::bigint or r.draft is distinct from item->'draft'
  or coalesce(previous.number,0)+1 is distinct from (item->>'next_number')::integer
  or previous.id is distinct from (item->>'previous_version_id')::uuid then raise exception 'Et valgt utkast er endret. Vurder utvalget på nytt.' using errcode='40001';end if;
  if previous.id is not null and previous.content=r.draft then raise exception 'Rutinen er allerede godkjent uten nye endringer.' using errcode='40001';end if;
  perform kshms_private.validate_draft(r.draft);
 end loop;
 summary:=trim(p_assessment)||E'\n\n'||p_approval_statement;
 for item in select value from jsonb_array_elements(p_routines) order by value->>'id' loop
  v:=public.kshms_command(p_company_id,'publish',jsonb_build_object('id',item->>'id','revision',item->'revision','change_summary',summary,'requires_ack',p_requires_ack,'acknowledge_self',p_acknowledge_self,'self_statement',p_self_statement));
  result:=result||jsonb_build_array(jsonb_build_object('id',v->'id','routine_id',v->'routine_id','number',v->'number','published_at',v->'published_at','published_by',v->'published_by'));
 end loop;
 return jsonb_build_object('versions',result,'published_count',jsonb_array_length(result));
end$function$

CREATE OR REPLACE FUNCTION public.kshms_sja_command(p_company_id uuid, p_action text, p_request_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x jsonb; s public.kshms_sjas%rowtype; receipt public.kshms_sja_commands%rowtype; sja_id uuid; content_data jsonb; leader uuid; payload_digest text; result jsonb; linked_project uuid;
 statement_value constant text:='Jeg har gjennomgått denne SJA-en sammen med deltakerne. Arbeidsoppgaven, farene, tiltakene og beredskapen er vurdert for forholdene på stedet. Nødvendige tiltak er kontrollert før arbeidet starter. Ved endringer eller uavklart risiko stanser vi og vurderer arbeidet på nytt.';
begin
 x:=kshms_private.require_context(p_company_id);
 perform 1 from public.company_module_access where company_id=p_company_id and module_key='kshms' for update;
 x:=kshms_private.require_context(p_company_id);
 if p_action is null or p_action not in ('save','sign') or p_request_id is null or jsonb_typeof(p_payload) is distinct from 'object' then raise exception 'Ugyldig SJA-kommando.'; end if;
 payload_digest:=encode(sha256(convert_to(p_action||p_payload::text,'UTF8')),'hex');
 select * into receipt from public.kshms_sja_commands where company_id=p_company_id and request_id=p_request_id;
 if found then
  if receipt.actor_id<>auth.uid() or receipt.payload_hash<>payload_digest then raise exception 'Forespørselen er brukt med annen tekst eller bruker.' using errcode='40001'; end if;
  if nullif(receipt.result#>>'{sja,project_id}','') is not null then perform kshms_private.project_checklist_access(p_company_id,(receipt.result#>>'{sja,project_id}')::uuid,false); end if;
  return receipt.result;
 end if;
 sja_id:=(p_payload->>'id')::uuid;
 if sja_id is null then raise exception 'SJA-ID mangler.'; end if;
 select * into s from public.kshms_sjas where id=sja_id and company_id=p_company_id for update;
 if found then
  if s.status='signed' then raise exception 'SJA-en er signert og kan ikke endres.' using errcode='42501'; end if;
  if not ((x->>'manage')::boolean or s.created_by=auth.uid() or s.leader_id=auth.uid()) then raise exception 'Du kan ikke endre denne SJA-en.' using errcode='42501'; end if;
  if s.revision<>coalesce((p_payload->>'revision')::bigint,-1) then raise exception 'En kollega har lagret en nyere SJA. Sammenlign før du fortsetter.' using errcode='40001'; end if;
 else
  if exists(select 1 from public.kshms_sjas other where other.id=sja_id) then raise exception 'SJA-en er ikke tilgjengelig.' using errcode='42501'; end if;
  if coalesce((p_payload->>'revision')::bigint,-1)<>0 then raise exception 'SJA-en ble ikke funnet. Kladden er beholdt.' using errcode='40001'; end if;
 end if;
 linked_project:=case when p_payload ? 'project_id' then nullif(p_payload->>'project_id','')::uuid else s.project_id end;
 if s.id is not null and s.project_id is distinct from linked_project then raise exception 'SJA-en kan ikke flyttes til et annet prosjekt. Lag en ny analyse fra riktig prosjekt.' using errcode='42501'; end if;
 if linked_project is not null then perform kshms_private.project_checklist_access(p_company_id,linked_project,true); end if;
 content_data:=kshms_private.sja_content(p_payload->'content',p_action='sign');leader:=nullif(content_data->>'leader_id','')::uuid;
 if leader is not null and not kshms_private.deviation_member(p_company_id,leader) then raise exception 'Velg en aktiv intern prosjektleder med KS/HMS-tilgang.' using errcode='42501'; end if;
 if p_action='sign' and (leader<>auth.uid() or p_payload->>'statement' is distinct from statement_value or p_payload->'prepared' is distinct from 'true'::jsonb) then raise exception 'Bare valgt ansvarlig prosjektleder kan signere etter egen bekreftelse.' using errcode='42501'; end if;
 if s.id is null then
  insert into public.kshms_sjas(id,company_id,project_id,content,leader_id,leader_identity,created_by,creator_identity,updated_by)
  values(sja_id,p_company_id,linked_project,content_data,leader,case when leader is null then null else kshms_private.identity_snapshot(leader) end,auth.uid(),kshms_private.identity_snapshot(auth.uid()),auth.uid()) returning * into s;
 else
  update public.kshms_sjas set content=content_data,leader_id=leader,leader_identity=case when leader is null then null else kshms_private.identity_snapshot(leader) end,revision=revision+1,updated_by=auth.uid(),updated_at=now() where id=s.id returning * into s;
 end if;
 if p_action='sign' then
  update public.kshms_sjas set status='signed',signed_by=auth.uid(),signed_identity=kshms_private.identity_snapshot(auth.uid()),signed_at=now(),statement=statement_value where id=s.id returning * into s;
 end if;
 result:=jsonb_build_object('sja',to_jsonb(s));
 insert into public.kshms_sja_commands(company_id,request_id,actor_id,payload_hash,result) values(p_company_id,p_request_id,auth.uid(),payload_digest,result);
 insert into public.kshms_audit(company_id,actor_id,action,object_id) values(p_company_id,auth.uid(),'sja-'||p_action,s.id);
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.organization_command(p_company_id uuid, p_revision integer, p_action text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x jsonb;a boolean;rev integer;target uuid;parent uuid;manager uuid;unitrow org_private.units%rowtype;
 e hr_private.employees%rowtype;subject uuid;oldunit uuid;newunit uuid;leader uuid;oldleader uuid;keys text[];depth integer;height integer;
begin
 x:=org_private.require_context(p_company_id);
 -- Consistent order: optional HR firm before company row. HR leader/closure writes
 -- serialize on that same HR lock; KS-only companies need no HR registration.
 perform 1 from hr_private.firms where company_id=p_company_id for update;
 perform 1 from public.sales_company_scopes where id=p_company_id for update;
 x:=org_private.require_context(p_company_id);a:=(x->>'administer')::boolean;
 select revision into rev from org_private.settings where company_id=p_company_id;
 if p_revision is distinct from coalesce(rev,0) then raise exception 'Organisasjonskartet er endret. Hent på nytt.' using errcode='40001';end if;
 if jsonb_typeof(p_payload) is distinct from 'object' or pg_column_size(p_payload)>2500
  or p_action is null or p_action not in ('unit','remove_unit','place','unplace') then raise exception 'Ugyldig karthandling.' using errcode='22023';end if;
 keys:=case p_action when 'unit' then array['id','parent_id','name','manager_id','color'] when 'remove_unit' then array['id']
  when 'place' then array['employee_id','employee_revision','unit_id','title','kind','leader_id','confirm_leader_change']
  else array['employee_id','employee_revision'] end;
 if exists(select 1 from jsonb_object_keys(p_payload)k where not k=any(keys)) then raise exception 'Bare organisasjonsfelt kan lagres her.' using errcode='22023';end if;
 if p_action in ('unit','remove_unit') then
  target:=(p_payload->>'id')::uuid;
  if target is not null then
   select * into unitrow from org_private.units where company_id=p_company_id and id=target;
   if unitrow.id is null or not org_private.can_edit(p_company_id,target,auth.uid())
   then raise exception 'Avdelingen er ikke tilgjengelig for endring.' using errcode='42501';end if;
  end if;
  if p_action='remove_unit' then
   if target is null then raise exception 'Velg avdeling.' using errcode='22023';end if;
   if exists(select 1 from org_private.units where company_id=p_company_id and parent_id=target)
    or exists(select 1 from org_private.placements where company_id=p_company_id and unit_id=target)
   then raise exception 'Flytt medarbeidere og underavdelinger først.' using errcode='22023';end if;
   delete from org_private.units where company_id=p_company_id and id=target;
  else
   parent:=(p_payload->>'parent_id')::uuid;manager:=(p_payload->>'manager_id')::uuid;
   if parent is not null and not exists(select 1 from org_private.units where company_id=p_company_id and id=parent)
   then raise exception 'Velg avdeling i samme firma.' using errcode='42501';end if;
   if not a and (target is null and (parent is null or not org_private.can_edit(p_company_id,parent,auth.uid()))
     or target is not null and parent is distinct from unitrow.parent_id
     or manager is distinct from unitrow.manager_id)
   then raise exception 'Firmaadmin styrer avdelingsflytting og redigeringstilgang.' using errcode='42501';end if;
   if manager is not null and not org_private.has_access(p_company_id,manager)
   then raise exception 'Velg aktiv avdelingsleder med KS/HMS-tilgang.' using errcode='42501';end if;
   if target is null and (select count(*) from org_private.units where company_id=p_company_id)>=100
   then raise exception 'Maksimalt 100 avdelinger i denne kartversjonen.' using errcode='54000';end if;
   with recursive parents as (
    select id,parent_id,array[id] path from org_private.units where company_id=p_company_id and id=parent
    union all select n.id,n.parent_id,p.path||n.id from parents p join org_private.units n
      on n.company_id=p_company_id and n.id=p.parent_id where not n.id=any(p.path)
   ) select max(cardinality(path)),bool_or(id=target)::integer into depth,height from parents;
   if target=parent or coalesce(height,0)=1 then raise exception 'Avdelingsstrukturen kan ikke gå i ring.' using errcode='22023';end if;
   with recursive children as (
    select id,array[id] path from org_private.units where company_id=p_company_id and id=target
    union all select n.id,p.path||n.id from children p join org_private.units n
      on n.company_id=p_company_id and n.parent_id=p.id where not n.id=any(p.path)
   ) select coalesce(max(cardinality(path)),1) into height from children;
   if coalesce(depth,0)+height>12 then raise exception 'Avdelingsstrukturen kan ha maksimalt 12 nivåer.' using errcode='22023';end if;
   if target is null then
    insert into org_private.units(company_id,parent_id,name,manager_id,color)
     values(p_company_id,parent,trim(p_payload->>'name'),manager,p_payload->>'color');
   else update org_private.units set parent_id=parent,name=trim(p_payload->>'name'),manager_id=manager,color=p_payload->>'color'
    where company_id=p_company_id and id=target;end if;
  end if;
 else
  subject:=(p_payload->>'employee_id')::uuid;
  if not hr_private.active_member(p_company_id,subject) then raise exception 'Medarbeideren er ikke aktiv i firmaet.' using errcode='42501';end if;
  select * into e from hr_private.employees where company_id=p_company_id and user_id=subject;
  if coalesce(e.revision,0) is distinct from (p_payload->>'employee_revision')::integer then raise exception 'Medarbeideren eller lederen er endret. Hent på nytt.' using errcode='40001';end if;
  select unit_id,leader_id into oldunit,oldleader from org_private.placements where company_id=p_company_id and user_id=subject;
  if e.id is not null then oldleader:=e.leader_id;end if;
  newunit:=case when p_action='place' then (p_payload->>'unit_id')::uuid else oldunit end;
  if not a and (oldunit is null or not org_private.can_edit(p_company_id,oldunit,auth.uid())
    or newunit is null or not org_private.can_edit(p_company_id,newunit,auth.uid()))
  then raise exception 'Du kan bare plassere medarbeidere innen egen avdeling.' using errcode='42501';end if;
  if p_action='unplace' then
   update org_private.placements set unit_id=null where company_id=p_company_id and user_id=subject;
  else
   if newunit is null or not exists(select 1 from org_private.units where company_id=p_company_id and id=newunit)
   then raise exception 'Velg avdeling i samme firma.' using errcode='42501';end if;
   leader:=(p_payload->>'leader_id')::uuid;
   if leader is not null and not hr_private.active_member(p_company_id,leader)
   then raise exception 'Velg aktiv leder i samme firma.' using errcode='42501';end if;
   if leader is distinct from oldleader then
    if not a then raise exception 'Firmaadmin må bekrefte lederbytter.' using errcode='42501';end if;
    if jsonb_typeof(p_payload->'confirm_leader_change') is distinct from 'boolean' or p_payload->>'confirm_leader_change' is distinct from 'true'
    then raise exception 'Bekreft lederendringen før lagring.' using errcode='22023';end if;
    if subject=leader or exists(with recursive managers as (
      select leader id,array[leader] path
      union all select case when h.id is not null then h.leader_id else o.leader_id end,
       p.path||case when h.id is not null then h.leader_id else o.leader_id end from managers p
       left join hr_private.employees h on h.company_id=p_company_id and h.user_id=p.id
       left join org_private.placements o on o.company_id=p_company_id and o.user_id=p.id
       where (case when h.id is not null then h.leader_id else o.leader_id end)=any(p.path) is not true
       and case when h.id is not null then h.leader_id else o.leader_id end is not null
    )select 1 from managers where id=subject)
    then raise exception 'Lederlinjen kan ikke gå i ring.' using errcode='22023';end if;
    if e.id is not null then
     if leader is not null and not hr_private.has_module_access(p_company_id,leader) then raise exception 'Velg aktiv nærmeste leder med HR-modultilgang.' using errcode='42501';end if;
     -- The established HR RPC remains the sole authority for individual grants.
     perform public.hr_employee_command(p_company_id,'leader',jsonb_build_object('id',e.id,'revision',e.revision,
       'leader_id',leader,'clear_old_leader_reader',true));
    end if;
   end if;
   insert into org_private.placements(company_id,user_id,unit_id,leader_id,title,kind)
    values(p_company_id,subject,newunit,leader,trim(p_payload->>'title'),p_payload->>'kind')
    on conflict(company_id,user_id)do update set unit_id=excluded.unit_id,leader_id=excluded.leader_id,title=excluded.title,kind=excluded.kind;
  end if;
 end if;
 insert into org_private.settings(company_id,revision)values(p_company_id,1)
 on conflict(company_id)do update set revision=org_private.settings.revision+1;
 return public.organization_state(p_company_id);
end$function$

CREATE OR REPLACE FUNCTION public.organization_group_command(p_company_id uuid, p_group_id uuid, p_revision integer, p_action text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x jsonb;items jsonb;item jsonb;ids uuid[];removed uuid[];confirmed uuid[];keys text[];written integer;c uuid;subject uuid;unit uuid;begin
 x:=org_private.group_context(p_company_id,p_group_id,true);
 perform org_private.group_lock(p_group_id);
 x:=org_private.group_context(p_company_id,p_group_id,true);
 if p_revision is distinct from (select revision from org_private.groups where id=p_group_id) then raise exception 'Felleskartet er endret. Hent på nytt.' using errcode='40001';end if;
 if jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>50000 or p_action is null or p_action not in ('layout','place','unplace','remove_group') then raise exception 'Ugyldig felleskarthandling.' using errcode='22023';end if;
 keys:=case p_action when 'layout' then array['chart_name','units','removed_ids','confirm_removal','shared_visibility'] when 'place' then array['employee_id','company_id','user_id','unit_id','title','kind'] when 'unplace' then array['employee_id','company_id','user_id'] else array['confirm'] end;
 if exists(select 1 from jsonb_object_keys(p_payload) k where not k=any(keys)) then raise exception 'Bare felleskartfelt kan lagres.' using errcode='22023';end if;
 if p_action='remove_group' then
 if jsonb_typeof(p_payload->'confirm') is distinct from 'boolean' or p_payload->>'confirm' is distinct from 'true' then raise exception 'Bekreft sletting av felleskartet.' using errcode='22023';end if;
 delete from org_private.group_placements where group_id=p_group_id;
 update org_private.group_units set parent_id=null where group_id=p_group_id;
 delete from org_private.groups where id=p_group_id;
 return public.organization_group_options(p_company_id);
 elsif p_action='layout' then
 if p_payload?'shared_visibility' and jsonb_typeof(p_payload->'shared_visibility') is distinct from 'boolean' then raise exception 'Kryss av for felles visning.' using errcode='22023';end if;
 items:=p_payload->'units';
 if jsonb_typeof(items) is distinct from 'array' or jsonb_array_length(items)>100 or jsonb_typeof(p_payload->'chart_name') is distinct from 'string' or length(trim(p_payload->>'chart_name')) not between 2 and 100 then raise exception 'Kontroller toppnavn og maks 100 avdelinger.' using errcode='22023';end if;
 for item in select value from jsonb_array_elements(items) loop
 if jsonb_typeof(item) is distinct from 'object' or exists(select 1 from jsonb_object_keys(item) k where k not in ('id','parent_id','company_id','name','manager_id','color','sort_order')) or jsonb_typeof(item->'id') is distinct from 'string' or jsonb_typeof(item->'name') is distinct from 'string' or length(trim(item->>'name')) not between 2 and 80 or jsonb_typeof(item->'color') is distinct from 'string' or item->>'color' not in ('teal','blue','amber','violet','rose') or exists(select 1 from unnest(array['parent_id','company_id','manager_id']) k where item?k and jsonb_typeof(item->k) not in ('string','null')) then raise exception 'Kontroller kortfeltene.' using errcode='22023';end if;
 if item?'sort_order' and (jsonb_typeof(item->'sort_order') is distinct from 'number' or (item->>'sort_order') !~ '^(0|[1-9][0-9]?|100)$') then raise exception 'Rekkefølgen må være et heltall fra 0 til 100.' using errcode='22023';end if;
 perform (item->>'id')::uuid,(item->>'parent_id')::uuid,(item->>'company_id')::uuid,(item->>'manager_id')::uuid;
 if (item->>'company_id') is not null and not exists(select 1 from org_private.group_companies where group_id=p_group_id and company_id=(item->>'company_id')::uuid) then raise exception 'Velg firma som tilhører kartet.' using errcode='42501';end if;

 end loop;
 select coalesce(array_agg((v->>'id')::uuid),'{}') into ids from jsonb_array_elements(items)v;
 if cardinality(ids)<>(select count(distinct i)from unnest(ids)i) or exists(select 1 from org_private.group_units where id=any(ids) and group_id<>p_group_id) then raise exception 'Duplisert eller fremmed kort-ID.' using errcode='42501';end if;
 if exists(select 1 from jsonb_array_elements(items)v where v->>'parent_id' is not null and (v->>'parent_id')::uuid=any(ids) is not true) then raise exception 'Overordnet avdeling mangler.' using errcode='22023';end if;
 if exists(with recursive walk as(select (v->>'id')::uuid id,(v->>'parent_id')::uuid parent_id,(v->>'company_id')::uuid firm,array[(v->>'id')::uuid] path,false bad from jsonb_array_elements(items)v
 union all select w.id,(v->>'parent_id')::uuid,coalesce(w.firm,(v->>'company_id')::uuid),w.path||(v->>'id')::uuid,w.bad or (v->>'id')::uuid=any(w.path) or w.firm is not null and v->>'company_id' is not null and w.firm<>(v->>'company_id')::uuid from walk w join jsonb_array_elements(items)v on (v->>'id')::uuid=w.parent_id where not w.bad and cardinality(w.path)<=12)
 select 1 from walk where bad or cardinality(path)>12) then raise exception 'Kontroller loop, dybde og firmagrense.' using errcode='22023';end if;
 select coalesce(array_agg(id order by id),'{}')into removed from org_private.group_units where group_id=p_group_id and id<>all(ids);
 if jsonb_typeof(p_payload->'removed_ids') is distinct from 'array' or jsonb_typeof(p_payload->'confirm_removal') is distinct from 'boolean' then raise exception 'Kontroller slettingsbekreftelsen.' using errcode='22023';end if;
 select coalesce(array_agg(value::uuid order by value::uuid),'{}') into confirmed from jsonb_array_elements_text(p_payload->'removed_ids');
 if removed is distinct from confirmed or cardinality(removed)>0 and p_payload->>'confirm_removal' is distinct from 'true' then raise exception 'Bekreft nøyaktig hvilke kort som fjernes.' using errcode='22023';end if;
 update org_private.group_units set parent_id=null where group_id=p_group_id;
 insert into org_private.group_units(id,group_id,parent_id,company_id,name,manager_id,color,sort_order) select (v->>'id')::uuid,p_group_id,null,(v->>'company_id')::uuid,trim(v->>'name'),(v->>'manager_id')::uuid,v->>'color',coalesce((v->>'sort_order')::integer,(select sort_order from org_private.group_units where id=(v->>'id')::uuid and group_id=p_group_id),0) from jsonb_array_elements(items)v
 on conflict(id)do update set company_id=excluded.company_id,name=excluded.name,manager_id=excluded.manager_id,color=excluded.color,sort_order=excluded.sort_order where org_private.group_units.group_id=p_group_id;
 get diagnostics written=row_count;if written<>jsonb_array_length(items) then raise exception 'Kort-ID kolliderer med annet kart.' using errcode='42501';end if;
 update org_private.group_units u set parent_id=(v->>'parent_id')::uuid from jsonb_array_elements(items)v where u.group_id=p_group_id and u.id=(v->>'id')::uuid;
 update org_private.group_placements set unit_id=null where group_id=p_group_id and unit_id=any(removed);
 delete from org_private.group_units where group_id=p_group_id and id=any(removed);
 if exists(select 1 from org_private.group_units u where u.group_id=p_group_id and u.manager_id is not null and not org_private.group_manager(p_group_id,u.id,u.manager_id)) then raise exception 'Velg kartleder med KS/HMS i grenen, eller alle firmaer for et felles nivå.' using errcode='42501';end if;
 -- Moving a company boundary must not silently move a person's placement to another firm.
 if exists(select 1 from org_private.group_placements p where p.group_id=p_group_id and p.unit_id is not null and org_private.group_unit_company(p_group_id,p.unit_id) is distinct from p.company_id) then raise exception 'Flytt medarbeiderne før du endrer firma på en gren.' using errcode='22023';end if;
 update org_private.groups set name=trim(p_payload->>'chart_name'),shared_visibility=coalesce((p_payload->>'shared_visibility')::boolean,shared_visibility) where id=p_group_id;
 else
 c:=(p_payload->>'company_id')::uuid;subject:=(p_payload->>'user_id')::uuid;unit:=(p_payload->>'unit_id')::uuid;
 if p_payload->>'employee_id' is distinct from c::text||':'||subject::text or not exists(select 1 from org_private.group_companies where group_id=p_group_id and company_id=c) or not hr_private.active_member(c,subject) then raise exception 'Velg aktiv person i tilknyttet firma.' using errcode='42501';end if;
 if p_action='unplace' then update org_private.group_placements set unit_id=null where group_id=p_group_id and company_id=c and user_id=subject;
 else
 if unit is null or org_private.group_unit_company(p_group_id,unit) is distinct from c then raise exception 'Velg avdeling i personens firmagren.' using errcode='42501';end if;
 if jsonb_typeof(p_payload->'title') is distinct from 'string' or length(trim(p_payload->>'title')) not between 2 and 100 or jsonb_typeof(p_payload->'kind') is distinct from 'string' or p_payload->>'kind' not in ('leader','middle','employee','apprentice') then raise exception 'Kontroller stilling og rolle.' using errcode='22023';end if;
 insert into org_private.group_placements(group_id,company_id,user_id,unit_id,title,kind)values(p_group_id,c,subject,unit,trim(p_payload->>'title'),p_payload->>'kind') on conflict(group_id,company_id,user_id)do update set unit_id=excluded.unit_id,title=excluded.title,kind=excluded.kind;
 end if;
 end if;
 update org_private.groups set revision=revision+1 where id=p_group_id;
 return public.organization_group_state(p_company_id,p_group_id);
end$function$

CREATE OR REPLACE FUNCTION public.organization_group_create(p_company_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare g uuid;board uuid:=gen_random_uuid();ids uuid[];c uuid;name text;begin
 perform org_private.require_context(p_company_id);
 if jsonb_typeof(p_payload) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('id','name','company_ids','confirm','shared_visibility')) or jsonb_typeof(p_payload->'confirm') is distinct from 'boolean' or p_payload->>'confirm' is distinct from 'true' or jsonb_typeof(p_payload->'company_ids') is distinct from 'array' or jsonb_typeof(p_payload->'name') is distinct from 'string' or length(trim(p_payload->>'name')) not between 2 and 100 or p_payload?'shared_visibility' and jsonb_typeof(p_payload->'shared_visibility') is distinct from 'boolean' or octet_length(p_payload::text)>5000 then raise exception 'Kontroller navnet, firmaene og bekreft opprettelsen.' using errcode='22023';end if;
 select array_agg(value::uuid order by value::uuid) into ids from jsonb_array_elements_text(p_payload->'company_ids');
 if cardinality(ids) not between 2 and 10 or (select count(distinct i)from unnest(ids)i)<>cardinality(ids) or p_company_id=any(ids) is not true then raise exception 'Velg 2–10 ulike firmaer, inkludert valgt firma.' using errcode='22023';end if;
 foreach c in array ids loop
 if not org_private.has_access(c,auth.uid()) or not exists(select 1 from public.sales_company_memberships where company_id=c and user_id=auth.uid() and workspace_role='firmaadmin') then raise exception 'Velg firmaer der du har KS/HMS og er firmaadmin.' using errcode='42501';end if;end loop;
 perform company_id from hr_private.firms where company_id=any(ids) order by company_id for update;
 perform id from public.sales_company_scopes where id=any(ids) order by id for update;
 perform org_private.require_context(p_company_id);
 foreach c in array ids loop
 if not org_private.has_access(c,auth.uid()) or not exists(select 1 from public.sales_company_memberships where company_id=c and user_id=auth.uid() and workspace_role='firmaadmin') then raise exception 'Firmatilgangen er endret.' using errcode='42501';end if;
 if (select count(*)from org_private.group_companies where company_id=c)>=10 then raise exception 'Maksimalt ti felleskart per firma.' using errcode='54000';end if;end loop;
 g:=(p_payload->>'id')::uuid;if g is null then raise exception 'Kart-ID mangler.' using errcode='22023';end if;
 if exists(select 1 from org_private.groups where id=g) then raise exception 'Kartet er allerede opprettet. Hent kartlisten på nytt.' using errcode='40001';end if;
 insert into org_private.groups(id,name,shared_visibility)values(g,trim(p_payload->>'name'),coalesce((p_payload->>'shared_visibility')::boolean,false));
 insert into org_private.group_companies(group_id,company_id)select g,i from unnest(ids)i;
 insert into org_private.group_units(id,group_id,name,color)values(board,g,'Styret','violet');
 insert into org_private.group_units(id,group_id,parent_id,company_id,name,color)select gen_random_uuid(),g,board,c.id,left(c.display_name,80),'teal' from public.sales_company_scopes c where c.id=any(ids);
 return public.organization_group_state(p_company_id,g);
end$function$

CREATE OR REPLACE FUNCTION public.organization_save_layout(p_company_id uuid, p_revision integer, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x jsonb;rev integer;items jsonb;removed uuid[];confirmed uuid[];written integer;
begin
 x:=org_private.require_context(p_company_id);
 if not coalesce((x->>'administer')::boolean,false) then raise exception 'Firmaadmin lagrer hele kartstrukturen.' using errcode='42501';end if;
 perform 1 from hr_private.firms where company_id=p_company_id for update;
 perform 1 from public.sales_company_scopes where id=p_company_id for update;
 x:=org_private.require_context(p_company_id);
 if not coalesce((x->>'administer')::boolean,false) then raise exception 'Firmaadmin lagrer hele kartstrukturen.' using errcode='42501';end if;
 select revision into rev from org_private.settings where company_id=p_company_id;
 if p_revision is distinct from coalesce(rev,0) then raise exception 'Kartet er endret. Behold kladden og hent den nye utgaven.' using errcode='40001';end if;
 if jsonb_typeof(p_payload) is distinct from 'object' or pg_column_size(p_payload)>45000
  or exists(select 1 from jsonb_object_keys(p_payload)k where k not in ('chart_name','units','removed_ids','confirm_removal'))
  or jsonb_typeof(p_payload->'chart_name') is distinct from 'string'
  or length(trim(p_payload->>'chart_name')) not between 2 and 100
  or p_payload->>'chart_name' ~ '[[:cntrl:]]'
  or jsonb_typeof(p_payload->'units') is distinct from 'array'
  or jsonb_typeof(p_payload->'removed_ids') is distinct from 'array'
  or jsonb_typeof(p_payload->'confirm_removal') is distinct from 'boolean'
 then raise exception 'Ugyldig kartkladd.' using errcode='22023';end if;
 items:=p_payload->'units';
 if jsonb_array_length(items)>100 or jsonb_array_length(p_payload->'removed_ids')>100 then raise exception 'Maksimalt 100 avdelinger.' using errcode='54000';end if;
 if exists(select 1 from jsonb_array_elements(items)v where jsonb_typeof(v) is distinct from 'object')
 then raise exception 'Ugyldig avdeling.' using errcode='22023';end if;
 if exists(select 1 from jsonb_array_elements(items)v where
  exists(select 1 from jsonb_object_keys(v)k where k not in ('id','parent_id','name','manager_id','color','sort_order'))
  or v?'sort_order' and (jsonb_typeof(v->'sort_order') is distinct from 'number' or (v->>'sort_order') !~ '^(0|[1-9][0-9]?|100)$')
  or jsonb_typeof(v->'id') is distinct from 'string' or jsonb_typeof(v->'name') is distinct from 'string'
  or jsonb_typeof(v->'color') is distinct from 'string'
  or coalesce(jsonb_typeof(v->'parent_id'),'null') not in ('string','null')
  or coalesce(jsonb_typeof(v->'manager_id'),'null') not in ('string','null'))
 then raise exception 'Bare organisasjonsfelt kan lagres her.' using errcode='22023';end if;
 if exists(select 1 from jsonb_to_recordset(items) as n(id uuid,parent_id uuid,name text,manager_id uuid,color text)
  where n.id is null or length(trim(n.name)) not between 2 and 80 or n.name ~ '[[:cntrl:]]'
  or n.color not in ('teal','blue','amber','violet','rose') or n.id=n.parent_id)
  or (select count(distinct n.id) from jsonb_to_recordset(items)as n(id uuid))<>jsonb_array_length(items)
 then raise exception 'Kontroller navn, farge og avdelings-ID-er.' using errcode='22023';end if;
 if exists(select 1 from jsonb_to_recordset(items)as n(id uuid) join org_private.units u on u.id=n.id where u.company_id<>p_company_id)
 then raise exception 'Avdelingen tilhører et annet firma.' using errcode='42501';end if;
 if exists(select 1 from jsonb_to_recordset(items)as n(parent_id uuid)
  where n.parent_id is not null and not exists(select 1 from jsonb_to_recordset(items)as p(id uuid)where p.id=n.parent_id))
 then raise exception 'Velg overordnet nivå i dette kartet.' using errcode='22023';end if;
 if exists(select 1 from jsonb_to_recordset(items)as n(manager_id uuid)
  where n.manager_id is not null and not org_private.has_access(p_company_id,n.manager_id))
 then raise exception 'Velg aktiv avdelingsleder med KS/HMS-tilgang.' using errcode='42501';end if;
 if exists(with recursive nodes as (select * from jsonb_to_recordset(items)as n(id uuid,parent_id uuid)),
  paths as (select id,parent_id,array[id] path,false loop from nodes
   union all select p.id,n.parent_id,p.path||n.id,n.id=any(p.path) from paths p join nodes n on n.id=p.parent_id
   where not p.loop and cardinality(p.path)<=12)
  select 1 from paths where loop or cardinality(path)>12)
 then raise exception 'Kartet kan ikke gå i ring eller ha mer enn 12 nivåer.' using errcode='22023';end if;
 select coalesce(array_agg(id order by id),'{}'::uuid[]) into removed from org_private.units u where company_id=p_company_id
  and not exists(select 1 from jsonb_to_recordset(items)as n(id uuid)where n.id=u.id);
 select coalesce(array_agg(value::uuid order by value::uuid),'{}'::uuid[]) into confirmed from jsonb_array_elements_text(p_payload->'removed_ids');
 if removed is distinct from confirmed or cardinality(removed)>0 and p_payload->>'confirm_removal'<>'true'
 then raise exception 'Bekreft nøyaktig hvilke avdelinger som skal slettes.' using errcode='22023';end if;
 -- All validation precedes writes. No HR leader/content/access function is called.
 -- One RPC transaction: failure at any point rolls the complete layout back.
 update org_private.units set parent_id=null where company_id=p_company_id;
 insert into org_private.units(id,company_id,parent_id,name,manager_id,color,sort_order)
  select n.id,p_company_id,null,trim(n.name),n.manager_id,n.color,coalesce(n.sort_order,(select sort_order from org_private.units where id=n.id and company_id=p_company_id),0)
   from jsonb_to_recordset(items)as n(id uuid,parent_id uuid,name text,manager_id uuid,color text,sort_order integer)
  on conflict(id)do update set name=excluded.name,manager_id=excluded.manager_id,color=excluded.color,sort_order=excluded.sort_order where org_private.units.company_id=p_company_id;
 get diagnostics written=row_count;
 if written<>jsonb_array_length(items) then raise exception 'Avdelings-ID er allerede i bruk. Hent kartet på nytt.' using errcode='42501';end if;
 update org_private.units u set parent_id=n.parent_id from jsonb_to_recordset(items)as n(id uuid,parent_id uuid)
  where u.company_id=p_company_id and u.id=n.id;
 update org_private.placements set unit_id=null where company_id=p_company_id and unit_id=any(removed);
 delete from org_private.units where company_id=p_company_id and id=any(removed);
 insert into org_private.settings(company_id,revision,chart_name)values(p_company_id,1,trim(p_payload->>'chart_name'))
  on conflict(company_id)do update set revision=org_private.settings.revision+1,chart_name=excluded.chart_name;
 return public.organization_state(p_company_id);
end$function$

CREATE OR REPLACE FUNCTION public.people_modules_company_set(p_company_id uuid, p_expected jsonb, p_kshms boolean, p_hr boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform kshms_private.require_module_manager(p_company_id);
 if not public.current_profile_is_systemadmin() then raise exception 'Bare systemadministrator kan aktivere kjøpte firmamoduler.' using errcode='42501'; end if;
 if p_kshms is null or p_hr is null then raise exception 'Velg begge moduler.' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('people-modules:'||p_company_id::text,0));
 perform 1 from public.company_module_access where company_id=p_company_id and module_key in ('kshms','hr') order by module_key for update;
 if public.people_modules_company_get(p_company_id) is distinct from p_expected then raise exception 'Firmaets tilgang er endret. Hent på nytt.' using errcode='40001'; end if;
 insert into public.company_module_access(company_id,module_key,enabled,granted_by) values(p_company_id,'kshms',p_kshms,auth.uid()),(p_company_id,'hr',p_hr,auth.uid())
 on conflict(company_id,module_key) do update set enabled=excluded.enabled,granted_by=excluded.granted_by,updated_at=now();
 insert into public.kshms_audit(company_id,actor_id,action) values(p_company_id,auth.uid(),'company_modules_changed');
 return public.people_modules_company_get(p_company_id);
end $function$

CREATE OR REPLACE FUNCTION public.people_modules_user_set(p_company_id uuid, p_user_id uuid, p_expected jsonb, p_kshms boolean, p_kshms_role text, p_hr boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x jsonb;
begin
 perform kshms_private.require_module_manager(p_company_id);
 if p_kshms is null or p_hr is null or p_kshms_role is null or p_kshms_role not in ('reader','responsible') then raise exception 'Ugyldige modulvalg.' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('people-modules:'||p_company_id::text,0));
 perform 1 from public.company_module_access where company_id=p_company_id and module_key in ('kshms','hr') order by module_key for update;
 x:=public.people_modules_user_get(p_company_id,p_user_id);
 if x is distinct from p_expected then raise exception 'Brukerens tilgang er endret. Hent på nytt.' using errcode='40001'; end if;
 if (x->>'firmaadmin')::boolean then raise exception 'Firmaadmins modultilgang følger firmaaktivering og firmarolle.' using errcode='42501'; end if;
 if p_kshms and not (x#>>'{company,kshms}')::boolean or p_hr and not (x#>>'{company,hr}')::boolean
 then raise exception 'Modulen må først aktiveres på firmaet av systemadministrator.' using errcode='42501'; end if;
 if p_hr and exists(select 1 from hr_private.closed_employments where company_id=p_company_id and user_id=p_user_id)
 then raise exception 'Avsluttet arbeidsforhold kan ikke få HR-tilgang.' using errcode='42501'; end if;
 if (not p_kshms or p_kshms_role<>'responsible') and exists(select 1 from public.kshms_settings where company_id=p_company_id and responsible_user_id=p_user_id)
 then raise exception 'Velg ny KS/HMS-ansvarlig i oppstarten før denne tilgangen fjernes.' using errcode='42501'; end if;
 insert into public.kshms_member_access(company_id,user_id,role,enabled,changed_by) values(p_company_id,p_user_id,p_kshms_role,p_kshms,auth.uid())
 on conflict(company_id,user_id) do update set role=excluded.role,enabled=excluded.enabled,changed_by=excluded.changed_by,changed_at=now();
 insert into hr_private.module_access(company_id,user_id,enabled,changed_by) values(p_company_id,p_user_id,p_hr,auth.uid())
 on conflict(company_id,user_id) do update set enabled=excluded.enabled,changed_by=excluded.changed_by,changed_at=now();
 insert into public.kshms_audit(company_id,actor_id,action,object_id) values(p_company_id,auth.uid(),'member_modules_changed',p_user_id);
 return public.people_modules_user_get(p_company_id,p_user_id);
end $function$

CREATE OR REPLACE FUNCTION public.project_checklist_command(p_company_id uuid, p_project_id uuid, p_action text, p_request_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
<<checklist_write>>
declare p public.projects%rowtype;r kshms_private.project_checklist_runs%rowtype;receipt kshms_private.project_checklist_receipts%rowtype;
 v public.kshms_checklist_versions%rowtype;instance jsonb;def jsonb;answers jsonb:='{}';a jsonb;item text;previous jsonb;req jsonb;
 rid uuid;category text;payload_hash text;result jsonb;predecessor uuid;canonical jsonb;prefix jsonb:='[]';vals jsonb;fields jsonb;begin
 p:=kshms_private.project_checklist_access(p_company_id,p_project_id,true);
 if p_request_id is null or p_action not in ('save','complete') or jsonb_typeof(p_payload) is distinct from 'object'
 then raise exception 'Ugyldig sjekklistelagring.';end if;
 payload_hash:=encode(sha256(convert_to(p_action||p_payload::text,'UTF8')),'hex');
 select * into receipt from kshms_private.project_checklist_receipts q where q.company_id=p_company_id and q.project_id=p_project_id and q.request_id=p_request_id;
 if found then
  if receipt.actor_id<>auth.uid() or receipt.payload_hash<>payload_hash then raise exception 'Lagringsforsøket er endret.' using errcode='40001';end if;
  return receipt.result;
 end if;
 rid:=(p_payload->>'id')::uuid;def:=p_payload->'definition';category:=def->>'category';
 if rid is null or nullif(trim(category),'') is null or length(category)>800 or jsonb_typeof(def->'items') is distinct from 'array'
 or jsonb_array_length(def->'items') not between 1 and 200 or jsonb_typeof(p_payload->'answers') is distinct from 'object'
 then raise exception 'Sjekklisten mangler gyldige punkter.';end if;
 select * into r from kshms_private.project_checklist_runs where id=rid;
 if found then
  if r.company_id<>p_company_id or r.project_id<>p_project_id or r.category<>category then raise exception 'Kontrollen tilhører et annet prosjekt.' using errcode='42501';end if;
  if r.status<>'draft' or r.revision<>coalesce((p_payload->>'revision')::bigint,-1) or (r.definition<>def and (category not like 'Egne sjekkpunkter%' or r.definition->>'source_version_id' is not null or def->>'source_version_id' is not null))
  then raise exception 'En annen person har lagret eller fullført denne kontrollen. Kladden er beholdt. Åpne den lagrede kontrollen og sammenlign.' using errcode='40001';end if;
 else
  select id into predecessor from kshms_private.project_checklist_runs q where q.project_id=p_project_id and q.category=checklist_write.category order by sequence desc limit 1;
  if coalesce((p_payload->>'revision')::bigint,-1)<>0 or predecessor is distinct from (p_payload->>'predecessor_id')::uuid
  or exists(select 1 from kshms_private.project_checklist_runs q where q.project_id=p_project_id and q.category=checklist_write.category and q.status='draft')
  then raise exception 'En annen person har startet eller lagret kontrollen. Kladden er beholdt. Åpne den lagrede kontrollen og sammenlign.' using errcode='40001';end if;
  select value into instance from jsonb_array_elements(coalesce(p.data#>'{project,kshmsChecklistInstances}','[]'::jsonb)) where value->>'category'=category limit 1;
  if instance is not null then
   select * into v from public.kshms_checklist_versions where id=(instance->>'version_id')::uuid and company_id=p_company_id;
   if v.id is null or def->>'source_version_id' is distinct from v.id::text
   or def->'items' is distinct from (select jsonb_agg(point->'title') from jsonb_array_elements(v.content->'points') point)
   or coalesce(def->'requirements','{}') is distinct from (select jsonb_object_agg(point->>'title',jsonb_build_object('image_required',point->'image_required','comment_required',point->'comment_required','guidance',point->'guidance')||case when point ? 'fields' then jsonb_build_object('fields',point->'fields') else '{}'::jsonb end||case when point->'allow_na'='false'::jsonb then jsonb_build_object('allow_na',false) else '{}'::jsonb end) from jsonb_array_elements(v.content->'points') point)
   then raise exception 'Den innhentede malutgaven er endret. Åpne sjekklisten på nytt.';end if;
  elsif def->>'source_version_id' is not null then raise exception 'Malutgaven finnes ikke i dette prosjektet.' using errcode='42501';end if;
 end if;
 if (select count(distinct value) from jsonb_array_elements_text(def->'items'))<>jsonb_array_length(def->'items') then raise exception 'Sjekkpunktene må ha ulik tekst.';end if;
 for item in select jsonb_array_elements_text(def->'items') loop
  if nullif(trim(item),'') is null or length(item)>2000 then raise exception 'Ugyldig sjekkpunkt.';end if;
  a:=coalesce(p_payload->'answers'->item,'{}'::jsonb);previous:=coalesce(p.data#>array['checklist',category,item],'{}'::jsonb);
  if jsonb_typeof(a)<>'object' or coalesce(a->>'status','') not in ('','Ok','Ikke aktuelt','Avvik','Lukket avvik')
  or length(coalesce(a->>'comment',''))>20000 or jsonb_typeof(coalesce(a->'photos','[]'))<>'array'
  or jsonb_array_length(coalesce(a->'photos','[]'))>100 then raise exception 'Ugyldig svar eller dokumentasjon.';end if;
  -- Preserve source links when starting the next control. The existing guard
  -- resolves their current authoritative status when the project is updated.
  if previous->>'ks_deviation_id' is not null then
   a:=a||jsonb_build_object('ks_deviation_id',previous->'ks_deviation_id','status',previous->'status',
    'closedAt',previous->'closedAt','closedBy',previous->'closedBy','closeComment',previous->'closeComment');
  elsif a->>'ks_deviation_id' is not null then raise exception 'Avvikslenken finnes ikke i prosjektet.';end if;
  req:=coalesce(def->'requirements'->item,'{}'::jsonb);
  if req->'allow_na'='false'::jsonb and a->>'status'='Ikke aktuelt' then raise exception 'Punktet kan ikke markeres som ikke aktuelt.';end if;
  if req ? 'fields' then
   fields:=kshms_private.checklist_fields(req->'fields');vals:=kshms_private.checklist_values(fields,coalesce(a->'values','{}'),p_action='complete' and coalesce(a->>'status','')<>'Ikke aktuelt');a:=a||jsonb_build_object('values',vals);
  end if;
  prefix:=kshms_private.checklist_prefix_add(prefix,req||jsonb_build_object('title',item),a);
  if req ? 'fields' then
   vals:=kshms_private.checklist_sign_values(fields,vals,coalesce(r.answers->item->'values','{}'),prefix);a:=a||jsonb_build_object('values',vals);
  end if;
  if p_action='complete' then
   req:=coalesce(def->'requirements'->item,'{}'::jsonb);
   if nullif(a->>'status','') is null then raise exception 'Vurder alle punktene før du fullfører. Mangler: %',item;end if;
   if a->>'status'<>'Ikke aktuelt' then
    if coalesce((req->>'documentation_either')::boolean,false) then
     if nullif(trim(a->>'comment'),'') is null and not exists(select 1 from jsonb_array_elements(coalesce(a->'photos','[]')) photo where nullif(trim(photo->>'url'),'') is not null) then raise exception 'Legg til bilde eller kommentar: %',item;end if;
    else
     if coalesce((req->>'comment_required')::boolean,false) and nullif(trim(a->>'comment'),'') is null then raise exception 'Legg til kommentar: %',item;end if;
     if coalesce((req->>'image_required')::boolean,false) and not exists(select 1 from jsonb_array_elements(coalesce(a->'photos','[]')) photo where nullif(trim(photo->>'url'),'') is not null) then raise exception 'Legg til bilde: %',item;end if;
    end if;
   end if;
  end if;
  answers:=answers||jsonb_build_object(item,a);
 end loop;
 if r.id is null then
  insert into kshms_private.project_checklist_runs(id,company_id,project_id,category,definition,answers,status,created_by,updated_by,updated_identity)
  values(rid,p_company_id,p_project_id,category,def,answers,'draft',auth.uid(),auth.uid(),kshms_private.identity_snapshot(auth.uid())) returning * into r;
 else
  update kshms_private.project_checklist_runs set answers=checklist_write.answers,definition=def,revision=revision+1,updated_at=now(),updated_by=auth.uid(),updated_identity=kshms_private.identity_snapshot(auth.uid()) where id=r.id returning * into r;
 end if;
 update public.projects set data=jsonb_set(coalesce(data,'{}'::jsonb),'{checklist}',
  jsonb_set(coalesce(data->'checklist','{}'::jsonb),array[category],coalesce(data->'checklist'->category,'{}'::jsonb)||answers,true),true),updated_at=now()
 where id=p_project_id returning data->'checklist'->category into canonical;
 select jsonb_object_agg(value,canonical->value) into answers from jsonb_array_elements_text(def->'items');
 update kshms_private.project_checklist_runs set answers=checklist_write.answers,
  status=case when p_action='complete' then 'completed' else 'draft' end,
  completed_at=case when p_action='complete' then now() end,completed_by=case when p_action='complete' then auth.uid() end,
  completed_identity=case when p_action='complete' then kshms_private.identity_snapshot(auth.uid()) end
 where id=r.id returning * into r;
 result:=jsonb_build_object('context',jsonb_build_object('company_id',p_company_id,'project_id',p_project_id,'user_id',auth.uid()),'run',to_jsonb(r),'answers',canonical);
 insert into kshms_private.project_checklist_receipts values(p_company_id,p_project_id,p_request_id,auth.uid(),payload_hash,result);
 insert into public.kshms_audit(company_id,actor_id,action,object_id) values(p_company_id,auth.uid(),'project-checklist-'||p_action,r.id);
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.project_progress_editor(p_project_id uuid, p_plan jsonb DEFAULT NULL::jsonb, p_customer_visible boolean DEFAULT NULL::boolean, p_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pr public.projects%rowtype;r public.project_progress_plans%rowtype;ctx jsonb;a jsonb;u jsonb;uid uuid;stored jsonb;people jsonb;begin
 select * into pr from public.projects where id=p_project_id for update;
 if not found or not public.project_progress_plan_access_allowed(p_project_id) then raise exception 'Prosjektet er ikke tilgjengelig.' using errcode='42501';end if;
 ctx:=progress_private.context(pr.company_scope_id);
 select * into r from public.project_progress_plans where project_id=p_project_id for update;
 if p_plan is not null then
  if not public.project_progress_plan_write_allowed(p_project_id) then raise exception 'Prosjektet er låst eller tilgangen er endret.' using errcode='42501';end if;
  if p_revision is distinct from coalesce(r.revision,0) then raise exception 'Planen er endret i en annen økt. Kladden er beholdt. Hent siste lagrede plan.' using errcode='40001';end if;
  if jsonb_typeof(p_plan) is distinct from 'object' or jsonb_typeof(p_plan->'activities') is distinct from 'array' then raise exception 'Ugyldig plan.' using errcode='22023';end if;
  if jsonb_array_length(p_plan->'activities')>500 or octet_length(p_plan::text)>2000000 then raise exception 'Planen er for stor.' using errcode='22023';end if;
  if p_plan ? 'excludeSundays' and jsonb_typeof(p_plan->'excludeSundays')<>'boolean' then raise exception 'Ugyldig søndagsvalg.' using errcode='22023';end if;
  if exists(select 1 from jsonb_array_elements(p_plan->'activities') z group by z->>'id' having count(*)>1) then raise exception 'Oppgavene må ha ulike ID-er.' using errcode='22023';end if;
  for a in select value from jsonb_array_elements(p_plan->'activities') loop
   if jsonb_typeof(a) is distinct from 'object' or coalesce(a->>'id','')='' or length(a->>'id')>200 or coalesce(trim(a->>'title'),'')='' or length(a->>'title')>200 or jsonb_typeof(a->'sessions') is distinct from 'array' then raise exception 'Ugyldig arbeidsoperasjon.' using errcode='22023';end if;
   if a ? 'crewSize' and a->'crewSize'<>'null'::jsonb and (jsonb_typeof(a->'crewSize')<>'number' or a->>'crewSize' !~ '^[0-9]{1,3}$' or (a->>'crewSize')::int<1) then raise exception 'Antall personer må være 1–999.' using errcode='22023';end if;
   if a ? 'nsCode' and coalesce(a->>'nsCode','')<>'' and (a->>'nsCode' !~ '^[2-7][0-9]{1,3}$' or coalesce(a->>'nsKind','building') not in ('building','system')) then raise exception 'Ugyldig NS-kode.' using errcode='22023';end if;
   if a ? 'assigneeIds' and (jsonb_typeof(a->'assigneeIds')<>'array' or jsonb_array_length(a->'assigneeIds')>50) then raise exception 'Velg høyst 50 deltakere.' using errcode='22023';end if;
   if exists(select 1 from jsonb_array_elements(coalesce(a->'assigneeIds','[]')) z group by z having count(*)>1) then raise exception 'Deltakere kan ikke gjentas.' using errcode='22023';end if;
   for u in select value from jsonb_array_elements(coalesce(a->'assigneeIds','[]')) loop
    if jsonb_typeof(u)<>'string' or u#>>'{}' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'Ugyldig deltaker-ID.' using errcode='22023';end if;
    uid:=(u#>>'{}')::uuid;
    if not progress_private.member(pr.company_scope_id,uid) and not exists(select 1 from progress_private.assignments x where x.project_id=p_project_id and x.activity_id=a->>'id' and x.user_id=uid)
    then raise exception 'Deltakeren må være aktiv i prosjektets firma.' using errcode='42501';end if;
   end loop;
   for u in select value from jsonb_array_elements(a->'sessions') loop
    if coalesce(u->>'date','') !~ '^\d{4}-\d{2}-\d{2}$' or to_char((u->>'date')::date,'YYYY-MM-DD')<>u->>'date' or coalesce(u->>'startTime','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or coalesce(u->>'endTime','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or u->>'startTime'>=u->>'endTime' then raise exception 'Ugyldig dato eller klokkeslett.' using errcode='22023';end if;
    if p_plan->>'excludeSundays'='true' and extract(isodow from (u->>'date')::date)=7 then raise exception 'Fjern søndagsøkter før lagring.' using errcode='22023';end if;
   end loop;
  end loop;
  stored:=p_plan||jsonb_build_object('activities',coalesce((select jsonb_agg(z.a-'assigneeIds' order by z.ord) from jsonb_array_elements(p_plan->'activities') with ordinality z(a,ord)),'[]'::jsonb));
  insert into public.project_progress_plans(project_id,company_scope_id,plan,customer_visible) values(p_project_id,pr.company_scope_id,stored,coalesce(p_customer_visible,false))
  on conflict(project_id) do update set plan=excluded.plan,customer_visible=excluded.customer_visible returning * into r;
  delete from progress_private.assignments where project_id=p_project_id;
  insert into progress_private.assignments select p_project_id,z.item->>'id',(w.item#>>'{}')::uuid from jsonb_array_elements(p_plan->'activities') z(item) cross join lateral jsonb_array_elements(coalesce(z.item->'assigneeIds','[]')) w(item);
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',coalesce(nullif(trim(concat_ws(' ',to_jsonb(p)->>'first_name',to_jsonb(p)->>'last_name')),''),nullif(to_jsonb(p)->>'full_name',''),split_part(p.email,'@',1))) order by p.id),'[]') into people from public.sales_company_memberships m join public.profiles p on p.id=m.user_id where m.company_id=pr.company_scope_id and progress_private.member(pr.company_scope_id,p.id);
 return jsonb_build_object('context',ctx,'people',people,'record',jsonb_build_object('id',pr.id,'company_id',pr.company_scope_id,'revision',coalesce(r.revision,0),'locked',coalesce(pr.locked,false),'customerVisible',coalesce(r.customer_visible,false),'plan',progress_private.with_assignments(pr.id,coalesce(r.plan,'{"version":1,"activities":[],"excludeSundays":true}'::jsonb))));
end$function$

CREATE OR REPLACE FUNCTION public.rename_my_company_display_name(p_company_id uuid, p_expected_name text, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();new_name text:=btrim(p_name);old_name text;primary_id uuid;begin
 if actor is null then raise exception 'Du må være innlogget.' using errcode='42501';end if;
 perform 1 from public.profiles where id=actor and approved and not coalesce(deactivated,false) for share;
 if not found then raise exception 'Brukeren må være godkjent og aktiv.' using errcode='42501';end if;
 primary_id:=public.current_primary_company_scope_id();
 if p_company_id is null or p_company_id is distinct from primary_id then raise exception 'Du kan bare endre ditt primærfirma her.' using errcode='42501';end if;
 perform 1 from public.sales_company_memberships where company_id=p_company_id and user_id=actor and workspace_role='firmaadmin' for share;
 if not found and not public.current_profile_is_systemadmin() then raise exception 'Bare firmaadmin eller systemadmin kan endre firmanavnet.' using errcode='42501';end if;
 if new_name is null or length(new_name) not between 2 and 100 or new_name ~ '[[:cntrl:]]' then raise exception 'Skriv et firmanavn med 2–100 tegn.' using errcode='22023';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('company-display-name:'||public.sales_normalize_company_name(new_name),0));
 select display_name into old_name from public.sales_company_scopes where id=p_company_id for update;
 if not found then raise exception 'Firmaet finnes ikke.' using errcode='P0002';end if;
 if old_name is distinct from p_expected_name then raise exception 'Firmanavnet er endret av andre. Hent navnet på nytt.' using errcode='40001';end if;
 if exists(select 1 from public.sales_company_scopes where id<>p_company_id and (normalized_name=public.sales_normalize_company_name(new_name) or public.sales_normalize_company_name(display_name)=public.sales_normalize_company_name(new_name))) then raise exception 'Navnet tilhører allerede et annet registrert firma.' using errcode='23505';end if;
 update public.sales_company_scopes set display_name=new_name where id=p_company_id;
 return public.get_my_company_profile();
end$function$

CREATE OR REPLACE FUNCTION public.save_company_customer(p_customer jsonb, p_id uuid DEFAULT NULL::uuid, p_expected_revision bigint DEFAULT NULL::bigint, p_expected_company_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_scope uuid:=public.company_customer_scope(); v_data jsonb; v_row public.company_customer_profiles%rowtype;
begin
 if p_expected_company_id is distinct from v_scope then raise exception 'Arbeidsfirmaet er endret. Åpne kunderegisteret på nytt.' using errcode='42501'; end if;
 v_data:=jsonb_build_object('customer',trim(coalesce(p_customer->>'customer','')),'email',trim(coalesce(p_customer->>'email','')),'phone',trim(coalesce(p_customer->>'phone','')),'address',trim(coalesce(p_customer->>'address','')),'postnr',trim(coalesce(p_customer->>'postnr','')),'city',trim(coalesce(p_customer->>'city','')));
 if v_data->>'customer'='' then raise exception 'Kundenavn må fylles ut.'; end if;
 if octet_length(v_data::text)>6000 then raise exception 'Kundeinformasjonen er for lang.'; end if;
 if p_id is null then
  insert into public.company_customer_profiles(company_id,customer,created_by) values(v_scope,v_data,auth.uid()) returning * into v_row;
 else
  update public.company_customer_profiles set customer=v_data,revision=revision+1,updated_at=now()
  where id=p_id and company_id=v_scope and revision=p_expected_revision returning * into v_row;
  if not found then raise exception 'Kunden er endret eller ikke tilgjengelig. Søk kunden på nytt.' using errcode='40001'; end if;
 end if;
 return jsonb_build_object('id',v_row.id,'customer',v_row.customer,'revision',v_row.revision);
end $function$

